import { faker } from "@faker-js/faker";
import { expect, test } from "@playwright/test";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

test.describe("Facility Location Tags", () => {
  let facilityId: string;

  test.beforeEach(() => {
    facilityId = getFacilityId();
  });

  test("A tagged location retains its questionnaire entry point and fullscreen fill route", async ({
    page,
  }) => {
    const tagName = `Loc Tag ${Date.now()}`;
    const locationName = faker.company.name();

    await test.step("Create a location tag config", async () => {
      await page.goto(`/facility/${facilityId}/settings/tag_config`);
      await page.getByRole("button", { name: "Add tag config" }).click();
      await page.getByRole("textbox", { name: "Display name *" }).fill(tagName);
      await page.getByRole("combobox", { name: "Category" }).click();
      await page.getByRole("option", { name: "Admin" }).click();
      await page.getByRole("combobox", { name: "Resource" }).click();
      await page.getByRole("option", { name: "Location" }).click();
      await page.getByRole("button", { name: "Create tag config" }).click();
      await expect(
        page
          .locator("li[data-sonner-toast]")
          .getByText("Tag Config created successfully"),
      ).toBeVisible();
    });

    await test.step("Create a location", async () => {
      await page.goto(`/facility/${facilityId}/settings/locations`);
      await page.getByRole("button", { name: "Add Location" }).click();
      await page.getByRole("textbox", { name: "Name" }).fill(locationName);
      await page.getByRole("button", { name: "Create" }).click();
      await expect(
        page.locator("li[data-sonner-toast]").getByText("Location Created"),
      ).toBeVisible();
    });

    await test.step("Assign tag to the location", async () => {
      await page
        .getByRole("textbox", { name: "Search by name" })
        .fill(locationName);
      await page.getByRole("button", { name: "Add tags" }).first().click();
      await page.getByText(tagName, { exact: true }).click();
      await expect(
        page
          .locator("li[data-sonner-toast]")
          .getByText("Tags updated successfully"),
      ).toBeVisible();
      await page.keyboard.press("Escape");
    });

    await test.step("Verify tag is shown on the location", async () => {
      await expect(
        page.getByRole("cell", { name: tagName }).first(),
      ).toBeVisible();
    });

    await test.step("Open a questionnaire alongside the location's tag controls", async () => {
      await page.getByRole("cell", { name: locationName, exact: true }).click();
      await expect(
        page.getByRole("heading", { name: locationName, exact: true }),
      ).toBeVisible();
      await expect(page.getByText(tagName, { exact: true })).toBeVisible();
      await expect(
        page.getByRole("button", { name: "Manage tags", exact: true }),
      ).toBeVisible();
      const locationUrl = page.url();

      await page
        .getByRole("button", { name: "Fill questionnaire", exact: true })
        .click();
      await expect(page.locator('[data-sidebar="sidebar"]')).toHaveCount(0);
      await page
        .getByRole("combobox", { name: "Select a questionnaire to fill" })
        .click();
      await page.getByPlaceholder("Search forms").fill("E2E Location");
      await page
        .getByRole("option", {
          name: "E2E Location Questionnaire",
          exact: true,
        })
        .click();
      await expect(
        page.getByRole("region", { name: "Form canvas" }),
      ).toBeVisible();
      await expect(page.locator('[data-sidebar="sidebar"]')).toHaveCount(0);
      await expect(
        page.getByRole("tab", { name: "Patient Clinical History" }),
      ).toHaveCount(0);
      await page.getByRole("button", { name: "Close", exact: true }).click();
      await expect(page).toHaveURL(locationUrl);
      await expect(page.getByText(tagName, { exact: true })).toBeVisible();
    });
  });
});
import { faker } from "@faker-js/faker";
import { expect, type Page, test } from "@playwright/test";
import {
  adminApiHeaders,
  apiBaseUrl,
  questionBlock,
} from "tests/helper/questionnaireV2";
import { getEncounterId } from "tests/support/encounterId";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

const TOGGLE_LABEL = "Show clinical section";
const SECTION_LABEL = "Clinical section";

async function openConditionalSection(page: Page, structuredType: string) {
  const suffix = faker.string.alphanumeric(12).toLowerCase();
  const response = await fetch(`${apiBaseUrl()}/api/v1/questionnaire/`, {
    method: "POST",
    headers: adminApiHeaders(),
    body: JSON.stringify({
      title: `E2E Structured State ${suffix}`,
      slug: `e2e-structured-state-${suffix}`,
      status: "active",
      subject_type: "encounter",
      auth_context: "instance",
      questions: [
        {
          id: faker.string.uuid(),
          link_id: "SHOW",
          text: TOGGLE_LABEL,
          type: "boolean",
          required: false,
          questions: [],
        },
        {
          id: faker.string.uuid(),
          link_id: "SECTION",
          text: SECTION_LABEL,
          type: "structured",
          structured_type: structuredType,
          required: false,
          enable_when: [{ question: "SHOW", operator: "equals", answer: true }],
          questions: [],
        },
      ],
    }),
  });
  expect(response.ok, await response.clone().text()).toBeTruthy();
  const questionnaire = (await response.json()) as { id: string };
  await page.goto(
    `/facility/${getFacilityId()}/patient/${getPatientId()}/encounter/${getEncounterId()}/questionnaire/${questionnaire.id}`,
  );
  await questionBlock(page, TOGGLE_LABEL)
    .getByRole("radio", { name: "Yes", exact: true })
    .click();
  await expect(questionBlock(page, SECTION_LABEL)).toBeVisible();
}

async function remountSection(page: Page) {
  const toggle = questionBlock(page, TOGGLE_LABEL);
  await toggle.getByRole("radio", { name: "No", exact: true }).click();
  await expect(questionBlock(page, SECTION_LABEL)).toHaveCount(0);
  await toggle.getByRole("radio", { name: "Yes", exact: true }).click();
  await expect(questionBlock(page, SECTION_LABEL)).toBeVisible();
}

test("file names and selections survive conditional remount and adding another file", async ({
  page,
}) => {
  await openConditionalSection(page, "files");
  const section = questionBlock(page, SECTION_LABEL);
  await section.locator('input[type="file"]').setInputFiles({
    name: "first.txt",
    mimeType: "text/plain",
    buffer: Buffer.from("first attachment"),
  });
  const names = section.getByPlaceholder("File Name", { exact: true });
  await names.first().fill("Original attachment");
  await remountSection(page);
  await expect(names).toHaveCount(1);
  await expect(names.first()).toHaveValue("Original attachment");
  await section.locator('input[type="file"]').setInputFiles({
    name: "second.txt",
    mimeType: "text/plain",
    buffer: Buffer.from("second attachment"),
  });
  await expect(names).toHaveCount(2);
  await expect(names.first()).toHaveValue("Original attachment");
  await expect(section.getByText("first.txt", { exact: true })).toBeVisible();
  await expect(section.getByText("second.txt", { exact: true })).toBeVisible();
});

for (const encounterClass of ["amb", "imp"]) {
  test(`encounter edits survive remount with immutable class and preserved terminal period (${encounterClass})`, async ({
    page,
  }) => {
    const periodEnd = "2025-01-02T00:00:00Z";
    await page.route(
      (url) => url.pathname === `/api/v1/encounter/${getEncounterId()}/`,
      async (route) => {
        const response = await route.fetch();
        await route.fulfill({
          response,
          json: {
            ...(await response.json()),
            encounter_class: encounterClass,
            status: "cancelled",
            period: { start: "2025-01-01T00:00:00Z", end: periodEnd },
          },
        });
      },
    );
