          ) : (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Lock className="size-8 text-gray-400 mb-2" />
              <p className="text-sm font-medium text-gray-700">
                {t("no_encounter_associated")}
              </p>
            </div>
          )}
