import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import query from "@/Utils/request/query";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";

interface LocationFormsProps {
  facilityId: string;
  locationId: string;
}

const FORMS_PER_PAGE = 15;

export default function LocationForms({
  facilityId,
  locationId,
}: LocationFormsProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const basePath = `/facility/${facilityId}/locations/${locationId}`;

  const {
    data: questionnaires,
    isLoading,
    isError,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: [
      ...questionnaireKeys.all,
      "location-forms",
      facilityId,
      locationId,
      search,
      page,
    ],
    queryFn: query.debounced(questionnaireApi.list, {
      queryParams: {
        subject_type: "location",
        status: "active",
        facility_or_instance: facilityId,
        title: search || undefined,
        limit: FORMS_PER_PAGE,
        offset: (page - 1) * FORMS_PER_PAGE,
      },
    }),
  });

  return (
    <Page
      title={t("submit_forms")}
      options={
        <Button variant="outline" asChild>
          <Link href={`${basePath}/responses`}>
            <ClipboardList className="size-4" />
            {t("view_responses")}
          </Link>
        </Button>
      }
    >
      <div
        className="space-y-5 px-3 py-4 md:px-0"
        data-cy="location-forms-page"
      >
        <p className="text-sm text-gray-600">
          {t("location_forms_description")}
        </p>

        <div className="relative w-full sm:max-w-sm">
          <Search
            className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-500"
            aria-hidden="true"
          />
          <Input
            aria-label={t("search_forms")}
            placeholder={t("search_forms")}
            value={search}
            onChange={(event) => {
              setSearch(event.target.value);
              setPage(1);
            }}
            className="pl-9"
          />
        </div>

        {isLoading ? (
          <div role="status" aria-label={t("loading")} className="space-y-3">
            {Array.from({ length: 5 }, (_, index) => (
              <Skeleton key={index} className="h-20 w-full rounded-lg" />
            ))}
          </div>
        ) : isError ? (
          <Alert variant="destructive">
            <AlertTitle>{t("error")}</AlertTitle>
            <AlertDescription>
              <p>{t("questionnaire_error_loading")}</p>
              <Button
                variant="outline"
                size="sm"
                onClick={() => void refetch()}
                disabled={isFetching}
                className="mt-2"
              >
                {t("try_again")}
              </Button>
            </AlertDescription>
          </Alert>
        ) : !questionnaires?.results.length ? (
          <EmptyState
            icon={<FileText className="size-6 text-gray-500" />}
            title={search ? t("no_results_found") : t("no_location_forms")}
            action={
              search ? (
                <Button
                  variant="outline"
                  onClick={() => {
                    setSearch("");
                    setPage(1);
                  }}
                >
                  {t("clear_search")}
                </Button>
              ) : undefined
            }
          />
        ) : (
          <>
            <ul className="divide-y divide-gray-200 overflow-hidden rounded-lg border border-gray-200 bg-white">
              {questionnaires.results.map((questionnaire) => (
                <li key={questionnaire.id}>
                  <Link
                    href={`${basePath}/questionnaire/${questionnaire.id}`}
                    data-cy="location-form-link"
                    className="group flex min-h-20 items-center gap-3 px-4 py-3 transition-colors hover:bg-gray-50 focus-visible:bg-gray-50 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-primary-600 sm:gap-4"
                  >
                    <div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-primary-50 text-primary-700">
                      <FileText className="size-5" aria-hidden="true" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="break-words text-sm font-medium text-gray-900 group-hover:text-primary-800">
                        {questionnaire.title}
                      </p>
                      {questionnaire.description && (
                        <p className="mt-1 line-clamp-2 break-words text-sm text-gray-600">
                          {questionnaire.description}
                        </p>
                      )}
                    </div>
                    <ArrowRight
                      className="size-4 shrink-0 text-gray-500 group-hover:text-primary-700"
                      aria-hidden="true"
                    />
                  </Link>
                </li>
              ))}
            </ul>
            <Pagination
              data={{ totalCount: questionnaires.count }}
              cPage={page}
              defaultPerPage={FORMS_PER_PAGE}
              onChange={setPage}
              className="flex justify-center"
            />
          </>
        )}
      </div>
    </Page>
  );
}
