import { useQuery } from "@tanstack/react-query";
import { AlertCircle, ClipboardList } from "lucide-react";
import { Link } from "raviger";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import Page from "@/components/Common/Page";
import Pagination from "@/components/Common/Pagination";
import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import query from "@/Utils/request/query";
import { formatDateTime, formatName } from "@/Utils/utils";
import locationApi from "@/types/location/locationApi";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import resourceQuestionnaireResponseApi, {
  ResourceQuestionnaireResponse,
} from "@/types/questionnaire/resourceQuestionnaireResponseApi";

import LocationResponseDetails from "./components/LocationResponseDetails";

interface LocationResponsesProps {
  facilityId: string;
  locationId: string;
}

const PAGE_SIZE = 20;

export default function LocationResponses({
  facilityId,
  locationId,
}: LocationResponsesProps) {
  const { t } = useTranslation();
  const [page, setPage] = useState(1);
  const [selectedResponse, setSelectedResponse] =
    useState<ResourceQuestionnaireResponse | null>(null);

  useEffect(() => {
    setPage(1);
    setSelectedResponse(null);
  }, [facilityId, locationId]);

  const locationQuery = useQuery({
    queryKey: ["location", facilityId, locationId],
    queryFn: query(locationApi.get, {
      pathParams: { facility_id: facilityId, id: locationId },
    }),
  });

  const responsesQuery = useQuery({
    queryKey: ["resourceResponses", facilityId, "location", locationId, page],
    queryFn: query(resourceQuestionnaireResponseApi.list, {
      queryParams: {
        subject_type: "location",
        subject_id: locationId,
        limit: PAGE_SIZE,
        offset: (page - 1) * PAGE_SIZE,
      },
    }),
    enabled: !!locationQuery.data,
  });

  const isLoading = locationQuery.isLoading || responsesQuery.isLoading;
  const isError = locationQuery.isError || responsesQuery.isError;
  const responses = responsesQuery.data?.results ?? [];
  const formsUrl = `/facility/${facilityId}/locations/${locationId}/forms`;

  return (
    <Page
      title={t("responses")}
      options={
        <Button asChild>
          <Link href={formsUrl}>
            <ClipboardList className="size-4" />
            {t("forms")}
          </Link>
        </Button>
      }
    >
      <div className="space-y-5 px-3 py-4 md:px-0">
        <p className="text-sm text-gray-600">
          {t("location_responses_description")}
        </p>

        {isError ? (
          <Alert variant="destructive">
            <AlertCircle />
            <AlertDescription>
              <p>{t("error_loading_location_responses")}</p>
              <Button
                variant="outline"
                size="sm"
                className="mt-2"
                onClick={() => {
                  if (locationQuery.isError) {
                    void locationQuery.refetch();
                  } else {
                    void responsesQuery.refetch();
                  }
                }}
              >
                {t("try_again")}
              </Button>
            </AlertDescription>
          </Alert>
        ) : isLoading ? (
          <TableSkeleton count={5} />
        ) : responses.length === 0 ? (
          <div className="flex flex-col items-center rounded-lg border border-dashed border-gray-300 bg-white px-6 py-12 text-center">
            <ClipboardList className="mb-4 size-8 text-gray-400" />
            <h3 className="font-semibold text-gray-900">
              {t("no_responses_found")}
            </h3>
            <p className="mt-1 max-w-sm text-sm text-gray-600">
              {t("location_responses_empty_description")}
            </p>
            <Button asChild variant="outline" className="mt-5">
              <Link href={formsUrl}>{t("forms")}</Link>
            </Button>
          </div>
        ) : (
          <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
            <Table>
              <TableHeader className="bg-gray-50">
                <TableRow>
                  <TableHead className="px-4">{t("questionnaire")}</TableHead>
                  <TableHead className="hidden sm:table-cell">
                    {t("submitted_on")}
                  </TableHead>
                  <TableHead className="hidden lg:table-cell">
                    {t("submitted_by")}
                  </TableHead>
                  <TableHead>{t("status")}</TableHead>
                  <TableHead className="px-4 text-right">
                    <span className="sr-only">{t("view_response")}</span>
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {responses.map((response) => (
                  <TableRow key={response.id}>
                    <TableCell className="max-w-sm px-4 py-4 whitespace-normal">
                      <p className="break-words font-medium text-gray-950">
                        {response.questionnaire.title}
                      </p>
                      <p className="mt-1 text-xs text-gray-500 sm:hidden">
                        {response.created_date
                          ? formatDateTime(response.created_date)
                          : t("unknown")}
                      </p>
                      <p className="mt-1 text-xs text-gray-500 lg:hidden">
                        {formatName(response.created_by)}
                      </p>
                    </TableCell>
                    <TableCell className="hidden text-gray-600 sm:table-cell">
                      {response.created_date
                        ? formatDateTime(response.created_date)
                        : t("unknown")}
                    </TableCell>
                    <TableCell className="hidden text-gray-600 lg:table-cell">
                      {formatName(response.created_by)}
                    </TableCell>
                    <TableCell>
                      <Badge
                        size="xs"
                        variant={
                          response.status ===
                          QuestionnaireResponseStatus.EnteredInError
                            ? "destructive"
                            : "green"
                        }
                      >
                        {t(response.status)}
                      </Badge>
                    </TableCell>
                    <TableCell className="px-4 text-right">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setSelectedResponse(response)}
                      >
                        {t("view")}
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {!isError && responsesQuery.data && (
          <div className="flex justify-center">
            <Pagination
              data={{ totalCount: responsesQuery.data.count }}
              defaultPerPage={PAGE_SIZE}
              cPage={page}
              onChange={setPage}
            />
          </div>
        )}
      </div>

      <Dialog
        open={!!selectedResponse}
        onOpenChange={(open) => {
          if (!open) setSelectedResponse(null);
        }}
      >
        {selectedResponse && (
          <DialogContent className="max-h-[calc(100dvh-2rem)] overflow-y-auto sm:max-w-3xl">
            <DialogHeader className="pr-6 text-left">
              <DialogTitle className="break-words leading-snug">
                {selectedResponse.questionnaire.title}
              </DialogTitle>
              <DialogDescription>
