import { useQuery } from "@tanstack/react-query";
import { ArrowRight, ClipboardList, FileText, Search } from "lucide-react";
import { Link } from "raviger";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";

import Page from "@/components/Common/Page";
import Pagination from "@/components/Common/Pagination";
import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import query from "@/Utils/request/query";
import locationApi from "@/types/location/locationApi";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";

interface LocationFormsProps {
  facilityId: string;
  locationId: string;
}

const FORMS_PER_PAGE = 15;

export default function LocationForms({
  facilityId,
  locationId,
}: LocationFormsProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const basePath = `/facility/${facilityId}/locations/${locationId}`;

  const {
    data: location,
    isPending: isLocationPending,
    isError: isLocationError,
    isFetching: isLocationFetching,
    refetch: refetchLocation,
  } = useQuery({
    queryKey: ["location", facilityId, locationId],
    queryFn: query(locationApi.get, {
      pathParams: { facility_id: facilityId, id: locationId },
    }),
  });

  const {
    data: questionnaires,
    isLoading,
    isError,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: [
      ...questionnaireKeys.all,
      "location-forms",
      facilityId,
      locationId,
      search,
      page,
    ],
    queryFn: query.debounced(questionnaireApi.list, {
      queryParams: {
        subject_type: "location",
        status: "active",
        facility_or_instance: facilityId,
        title: search || undefined,
        limit: FORMS_PER_PAGE,
        offset: (page - 1) * FORMS_PER_PAGE,
      },
    }),
    enabled: !!location && !isLocationError,
  });

  return (
    <Page
      title={t("submit_forms")}
      options={
        <Button variant="outline" asChild>
          <Link basePath="/" href={`${basePath}/responses`}>
            <ClipboardList className="size-4" />
            {t("view_responses")}
          </Link>
        </Button>
      }
    >
      <div
        className="space-y-5 px-3 py-4 md:px-0"
        data-cy="location-forms-page"
      >
        <div className="space-y-1">
