import { Fragment, ReactNode } from "react";
import { useTranslation } from "react-i18next";

import { formatDateTime } from "@/Utils/utils";
import { Question } from "@/types/questionnaire/question";
import {
  ResourceQuestionnaireAnswer,
  ResourceQuestionnaireAnswerValue,
  ResourceQuestionnaireResponse,
} from "@/types/questionnaire/resourceQuestionnaireResponseApi";

interface LocationResponseDetailsProps {
  response: ResourceQuestionnaireResponse;
}

export default function LocationResponseDetails({
  response,
}: LocationResponseDetailsProps) {
  const { t } = useTranslation();

  const formatValue = (
    answer: ResourceQuestionnaireAnswerValue,
    question: Question,
  ) => {
    let value = answer.value ?? "";
    if (value !== "") {
      if (question.type === "boolean") {
        value = value === "true" ? t("yes") : t("no");
      } else if (question.type === "date") {
        value = formatDateTime(value, "DD/MM/YYYY");
      } else if (question.type === "dateTime") {
        value = formatDateTime(value);
      } else if (question.type === "choice") {
        value =
          question.answer_option?.find((option) => option.value === value)
            ?.display || value;
      }
    }

    return [
      value,
      answer.coding?.display || answer.coding?.code,
      answer.unit?.display || answer.unit?.code,
    ]
      .filter((part) => part !== undefined && part !== null && part !== "")
      .join(" ");
  };

  const renderQuestions = (
    questions: Question[],
    answers: ResourceQuestionnaireAnswer[],
  ): ReactNode[] =>
    questions.flatMap((question) => {
      const answer = answers.find((entry) => entry.question_id === question.id);

      if (question.type === "group") {
        const groups = answer?.sub_results?.length
          ? answer.sub_results
          : [answers];
        return groups.flatMap((groupAnswers, index) => {
          const children = renderQuestions(
            question.questions ?? [],
            groupAnswers,
          );
          if (!children.length) return [];

          return [
            <div key={`${question.id}-${index}`} className="space-y-3">
              <h3 className="text-sm font-semibold text-gray-900">
                {question.text}
                {groups.length > 1 && ` (${index + 1})`}
              </h3>
              <div className="space-y-4 border-l-2 border-gray-200 pl-4">
                {children}
              </div>
            </div>,
          ];
        });
      }

      if (!answer || question.type === "display") return [];

      const values = answer.values
        .map((value) => formatValue(value, question))
        .filter((value) => value !== "");
      if (!values.length && !answer.note) return [];

      return [
        <dl
          key={question.id}
          className="grid gap-1 text-sm sm:grid-cols-[minmax(0,1fr)_minmax(0,2fr)] sm:gap-6"
        >
          <dt className="break-words text-gray-600">{question.text}</dt>
          <dd className="min-w-0 space-y-2">
            <p className="break-words whitespace-pre-wrap font-medium text-gray-950">
              {values.map((value, index) => (
                <Fragment key={index}>
                  {index > 0 && ", "}
                  {value}
                </Fragment>
              ))}
            </p>
            {answer.note && (
              <p className="break-words whitespace-pre-wrap text-gray-600">
                <span className="font-medium">{t("note")}: </span>
                {answer.note}
              </p>
            )}
          </dd>
        </dl>,
      ];
    });

  const questions = renderQuestions(
    response.questionnaire.questions,
    response.responses,
  );

  return (
    <div className="space-y-5">
      {questions.length ? (
        questions
      ) : (
        <p className="py-4 text-sm text-gray-500">{t("no_responses_found")}</p>
      )}
    </div>
  );
}
