import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { AlertCircle, ArrowDownWideNarrow, ChevronRight, ClipboardList, FilePlus2, FileText, Loader2, MapPin, RefreshCw, SearchX } from "lucide-react";
import { Link, useQueryParams } from "raviger";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

import { Avatar } from "@/components/Common/Avatar";
import Page from "@/components/Common/Page";
import Pagination from "@/components/Common/Pagination";
import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import query from "@/Utils/request/query";
import { formatDateTime, formatName } from "@/Utils/utils";
import locationApi from "@/types/location/locationApi";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import resourceQuestionnaireResponseApi from "@/types/questionnaire/resourceQuestionnaireResponseApi";

import LocationResponseFilters, { LocationResponseFilterValues } from "./components/LocationResponseFilters";
import LocationResponseViewer from "./components/LocationResponseViewer";

interface LocationResponsesProps {
  facilityId: string;
  locationId: string;
}

const PAGE_SIZE = 20;

export default function LocationResponses({ facilityId, locationId }: LocationResponsesProps) {
  const { t } = useTranslation();
  const [params, setParams] = useQueryParams();
  const parsedPage = Number(params.page);
  const page = Number.isSafeInteger(parsedPage) && parsedPage > 0 ? parsedPage : 1;
  const responseId = params.response || undefined;
  const filters: LocationResponseFilterValues = {
    questionnaire: params.questionnaire || undefined,
    questionnaireTitle: params.questionnaire_title || undefined,
    createdBy: params.created_by || undefined,
    creatorName: params.creator_name || undefined,
    status: Object.values(QuestionnaireResponseStatus).includes(params.status)
      ? (params.status as QuestionnaireResponseStatus) : undefined,
  };
  const hasFilters = !!(filters.questionnaire || filters.createdBy || filters.status);

  const updateParams = (patch: Record<string, string | undefined>, replace = false) => {
    setParams(Object.fromEntries(Object.entries({ ...params, ...patch }).filter(([, value]) => value !== undefined && value !== "")), { replace });
  };
  const handleFiltersChange = (patch: Partial<LocationResponseFilterValues>) => {
    const next = { ...filters, ...patch };
    updateParams({
      questionnaire: next.questionnaire,
      questionnaire_title: next.questionnaire ? next.questionnaireTitle : undefined,
      created_by: next.createdBy,
      creator_name: next.createdBy ? next.creatorName : undefined,
      status: next.status,
      page: undefined,
      response: undefined,
    });
  };
  const clearFilters = () => handleFiltersChange({ questionnaire: undefined, questionnaireTitle: undefined, createdBy: undefined, creatorName: undefined, status: undefined });

  const locationQuery = useQuery({
    queryKey: ["location", facilityId, locationId],
    queryFn: query(locationApi.get, { pathParams: { facility_id: facilityId, id: locationId } }),
  });
  const responsesQuery = useQuery({
    queryKey: ["resourceResponses", facilityId, "location", locationId, { page, questionnaire: filters.questionnaire, created_by: filters.createdBy, status: filters.status }],
    queryFn: query(resourceQuestionnaireResponseApi.list, {
      queryParams: { subject_type: "location", subject_id: locationId, questionnaire: filters.questionnaire, created_by: filters.createdBy, status: filters.status, limit: PAGE_SIZE, offset: (page - 1) * PAGE_SIZE },
    }),
    enabled: !!locationQuery.data && !locationQuery.isError,
    placeholderData: keepPreviousData,
  });
  const responses = responsesQuery.data?.results ?? [];
  const responseFromList = responses.find((response) => response.id === responseId);
  const detailQuery = useQuery({
    queryKey: ["resourceResponses", facilityId, "location", locationId, "detail", responseId],
    queryFn: query(resourceQuestionnaireResponseApi.get, {
      pathParams: { id: responseId ?? "" },
      queryParams: { subject_type: "location", subject_id: locationId },
    }),
    enabled: !!responseId && !!locationQuery.data && !locationQuery.isError && !responseFromList,
    retry: false,
  });
  const selectedResponse = responseFromList ?? detailQuery.data ?? null;
  const selectedIndex = responses.findIndex((response) => response.id === responseId);
  const isLoading = locationQuery.isPending || responsesQuery.isLoading;
  const isError = locationQuery.isError || responsesQuery.isError;
  const isUpdating = responsesQuery.isFetching && !isLoading;
  const totalCount = responsesQuery.data?.count ?? 0;
  const formsUrl = `/facility/${facilityId}/locations/${locationId}/forms`;
  const handleRefresh = () => void (locationQuery.isError ? locationQuery.refetch() : responsesQuery.refetch());
  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      toast.success(t("response_link_copied"));
    } catch {
      toast.error(t("response_link_copy_failed"));
    }
  };

  return (
    <Page title={t("responses")} options={<Button asChild><Link basePath="/" href={formsUrl}><FilePlus2 className="size-4" />{t("submit_forms")}</Link></Button>}>
      <div className="space-y-5 px-3 py-4 md:px-0" data-cy="location-responses-page">
        <div className="space-y-2">
          {locationQuery.data && (
            <Link basePath="/" href={`/facility/${facilityId}/locations/${locationId}/overview`} className="inline-flex max-w-full items-center gap-1.5 rounded-sm text-sm font-medium text-gray-700 underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-primary-600">
              <MapPin className="size-4 shrink-0 text-gray-400" aria-hidden="true" /><span className="break-words">{locationQuery.data.name}</span>
            </Link>
          )}
          <p className="text-sm text-gray-600">{t("location_responses_description")}</p>
        </div>

        <div className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-xs">
          <div className="border-b border-gray-200">
            <LocationResponseFilters facilityId={facilityId} value={filters} onChange={handleFiltersChange} />
          </div>
          <div className="flex min-h-14 flex-wrap items-center justify-between gap-3 border-b border-gray-200 px-4 py-3 sm:px-5">
            <div className="flex items-center gap-2.5" role="status" aria-live="polite">
              <h3 className="text-sm font-semibold text-gray-950">{hasFilters ? t("matching_submissions") : t("all_submissions")}</h3>
              {!isLoading && !isError && !responsesQuery.isPlaceholderData && <Badge variant="secondary" size="xs" className="rounded-full px-2 tabular-nums">{totalCount}</Badge>}
              {isUpdating && <Loader2 className="size-3.5 animate-spin text-gray-500" aria-label={t("updating_results")} />}
            </div>
            <div className="flex items-center gap-3">
              <span className="inline-flex items-center gap-1.5 text-xs text-gray-500"><ArrowDownWideNarrow className="size-3.5" aria-hidden="true" />{t("newest_first")}</span>
              <Button variant="ghost" size="icon" className="size-8 text-gray-500" aria-label={t("refresh")} title={t("refresh")} disabled={responsesQuery.isFetching || locationQuery.isFetching} onClick={handleRefresh}><RefreshCw className="size-4" /></Button>
            </div>
          </div>

          {isError ? (
            <div className="p-5"><Alert variant="destructive"><AlertCircle /><AlertDescription><p>{t("error_loading_location_responses")}</p><Button variant="outline" size="sm" className="mt-3" onClick={handleRefresh}>{t("try_again")}</Button></AlertDescription></Alert></div>
          ) : isLoading ? (
            <div className="p-4"><TableSkeleton count={5} /></div>
          ) : responses.length === 0 ? (
            <div className="flex min-h-72 flex-col items-center justify-center px-6 py-12 text-center">
              <div className="mb-4 flex size-12 items-center justify-center rounded-full bg-gray-100 text-gray-500">{hasFilters ? <SearchX className="size-6" /> : <ClipboardList className="size-6" />}</div>
              <h3 className="text-base font-semibold text-gray-950">{hasFilters ? t("no_matching_responses") : t("no_responses_found")}</h3>
              <p className="mt-2 max-w-sm text-sm leading-relaxed text-gray-600">{hasFilters ? t("no_matching_responses_description") : t("location_responses_empty_description")}</p>
              {hasFilters ? <Button variant="outline" className="mt-5" onClick={clearFilters}>{t("clear_filters")}</Button> : page > 1 ? <Button variant="outline" className="mt-5" onClick={() => updateParams({ page: undefined })}>{t("back_to_first_page")}</Button> : <Button asChild variant="outline" className="mt-5"><Link basePath="/" href={formsUrl}>{t("submit_forms")}</Link></Button>}
            </div>
          ) : (
            <div aria-busy={isUpdating} className={cn(responsesQuery.isPlaceholderData && "opacity-60")}>
              <Table>
                <TableHeader className="bg-gray-50/70">
                  <TableRow className="hover:bg-transparent">
                    <TableHead className="px-4 text-xs text-gray-500 sm:px-5">{t("questionnaire")}</TableHead>
                    <TableHead className="hidden text-xs text-gray-500 lg:table-cell">{t("submitted_by")}</TableHead>
                    <TableHead className="hidden text-xs text-gray-500 md:table-cell">{t("submitted_on")}</TableHead>
                    <TableHead className="hidden text-xs text-gray-500 md:table-cell">{t("status")}</TableHead>
                    <TableHead className="w-20 px-4 text-right"><span className="sr-only">{t("view_response")}</span></TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {responses.map((response) => {
                    const author = formatName(response.created_by);
                    const enteredInError = response.status === QuestionnaireResponseStatus.EnteredInError;
                    const statusBadge = <Badge size="xs" variant={enteredInError ? "destructive" : "secondary"} className={cn(!enteredInError && "border-transparent bg-primary-50 text-primary-800")}>{t(response.status)}</Badge>;
                    return (
                      <TableRow key={response.id} data-response-id={response.id} data-state={response.id === responseId ? "selected" : undefined} className="group cursor-pointer hover:bg-primary-50/40 focus-within:bg-primary-50/40 data-[state=selected]:bg-primary-50" onClick={() => { if (!responsesQuery.isPlaceholderData) updateParams({ response: response.id }); }}>
                        <TableCell className="max-w-sm whitespace-normal px-4 py-4 sm:px-5">
                          <div className="flex items-start gap-3">
                            <div className="hidden size-9 shrink-0 items-center justify-center rounded-lg border border-gray-100 bg-gray-50 text-gray-500 sm:flex"><FileText className="size-4" aria-hidden="true" /></div>
                            <div className="min-w-0 space-y-1.5">
                              <p id={`response-title-${response.id}`} className="break-words font-medium leading-snug text-gray-950">{response.questionnaire.title}</p>
                              <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-gray-500"><span className="font-mono tabular-nums" title={response.id}>#{response.id.slice(0, 8)}</span><span className="lg:hidden">{author}</span></div>
                              <div className="flex flex-wrap items-center gap-2 md:hidden"><span className="text-xs text-gray-500">{response.created_date ? formatDateTime(response.created_date, "DD MMM YYYY, h:mm A") : t("unknown")}</span>{statusBadge}</div>
                            </div>
                          </div>
                        </TableCell>
                        <TableCell className="hidden lg:table-cell"><div className="flex items-center gap-2.5"><Avatar name={author} className="size-7 shrink-0 rounded-full" /><span className="max-w-40 truncate text-gray-700" title={author}>{author}</span></div></TableCell>
                        <TableCell className="hidden md:table-cell"><p className="text-gray-700">{response.created_date ? formatDateTime(response.created_date, "DD MMM YYYY") : t("unknown")}</p>{response.created_date && <p className="mt-1 text-xs text-gray-500">{formatDateTime(response.created_date, "h:mm A")}</p>}</TableCell>
                        <TableCell className="hidden md:table-cell">{statusBadge}</TableCell>
                        <TableCell className="px-3 text-right sm:px-4"><Button variant="ghost" size="sm" className="h-10 gap-1 text-gray-600 hover:text-primary-800" disabled={responsesQuery.isPlaceholderData} aria-describedby={`response-title-${response.id}`} onClick={(event) => { event.stopPropagation(); updateParams({ response: response.id }); }}>{t("view")}<ChevronRight className="size-4" aria-hidden="true" /></Button></TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          )}

          {!isError && !isLoading && responsesQuery.data && responses.length > 0 && (
            <div className="flex flex-wrap items-center justify-between gap-3 border-t border-gray-200 px-4 py-3 sm:px-5"><p className="text-xs text-gray-500" aria-live="polite">{t("response_results_range", { start: (page - 1) * PAGE_SIZE + 1, end: Math.min(page * PAGE_SIZE, totalCount), total: totalCount })}</p><Pagination data={{ totalCount }} defaultPerPage={PAGE_SIZE} cPage={page} onChange={(nextPage) => updateParams({ page: nextPage === 1 ? undefined : String(nextPage), response: undefined })} className="flex items-center" /></div>
          )}
        </div>
      </div>

      <LocationResponseViewer
        open={!!responseId} response={selectedResponse} locationName={locationQuery.data?.name}
        isLoading={locationQuery.isPending || (!responseFromList && detailQuery.isPending)}
        error={locationQuery.isError || (!responseFromList && detailQuery.isError)}
        onRetry={() => void (locationQuery.isError ? locationQuery.refetch() : detailQuery.refetch())}
        onClose={() => updateParams({ response: undefined }, true)} onCopyLink={handleCopyLink}
        position={selectedIndex >= 0 ? selectedIndex + 1 : undefined} total={responses.length}
        onPrevious={selectedIndex > 0 && !responsesQuery.isPlaceholderData ? () => updateParams({ response: responses[selectedIndex - 1].id }, true) : undefined}
        onNext={selectedIndex >= 0 && selectedIndex < responses.length - 1 && !responsesQuery.isPlaceholderData ? () => updateParams({ response: responses[selectedIndex + 1].id }, true) : undefined}
      />
    </Page>
  );
}

