import { useInfiniteQuery } from "@tanstack/react-query";
import { Check, ChevronDown, Loader2, X } from "lucide-react";
import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  Command,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import UserSelector from "@/components/Common/UserSelector";
import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import query from "@/Utils/request/query";
import { formatName } from "@/Utils/utils";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import { UserReadMinimal } from "@/types/user/user";

export interface LocationResponseFilterValues {
  questionnaire?: string;
  questionnaireTitle?: string;
  createdBy?: string;
  creatorName?: string;
  status?: QuestionnaireResponseStatus;
}

interface LocationResponseFiltersProps {
  facilityId: string;
  value: LocationResponseFilterValues;
  onChange: (patch: Partial<LocationResponseFilterValues>) => void;
  disabled?: boolean;
}

const QUESTIONNAIRES_PER_PAGE = 30;

export default function LocationResponseFilters({
  facilityId,
  value,
  onChange,
  disabled = false,
}: LocationResponseFiltersProps) {
  const { t } = useTranslation();
  const id = useId();
  const [formsOpen, setFormsOpen] = useState(false);
  const [formSearch, setFormSearch] = useState("");
  const [selectedUser, setSelectedUser] = useState<UserReadMinimal>();

  const questionnairesQuery = useInfiniteQuery({
    queryKey: [
      ...questionnaireKeys.all,
      "location-response-filter",
      facilityId,
      formSearch,
    ],
    queryFn: ({ pageParam, signal }) =>
      query.debounced(questionnaireApi.list, {
        queryParams: {
          subject_type: "location",
          facility_or_instance: facilityId,
          title: formSearch || undefined,
          limit: QUESTIONNAIRES_PER_PAGE,
          offset: pageParam,
        },
      })({ signal }),
    initialPageParam: 0,
    getNextPageParam: (lastPage, pages) => {
      const offset = pages.length * QUESTIONNAIRES_PER_PAGE;
      return offset < lastPage.count ? offset : undefined;
    },
    enabled: formsOpen && !disabled,
  });

  const questionnaires =
    questionnairesQuery.data?.pages.flatMap((page) => page.results) ?? [];
  const hasFilters = !!(value.questionnaire || value.createdBy || value.status);

  return (
    <div
      role="group"
      aria-label={t("location_response_filter_label")}
      data-cy="location-response-filters"
      className="grid grid-cols-1 items-end gap-3 bg-gray-50 p-4 sm:grid-cols-2 lg:grid-cols-[minmax(0,1.35fr)_minmax(0,1fr)_minmax(0,0.85fr)_auto]"
    >
      <div className="min-w-0 space-y-1.5">
        <Label
          htmlFor={`${id}-questionnaire`}
          className="text-xs text-gray-600"
        >
          {t("questionnaire")}
        </Label>
        <Popover
          open={formsOpen}
          onOpenChange={(open) => {
            setFormsOpen(open);
            if (open) setFormSearch("");
          }}
        >
          <PopoverTrigger asChild>
            <Button
              id={`${id}-questionnaire`}
              type="button"
              variant="outline"
              role="combobox"
              aria-label={t("questionnaire")}
              aria-expanded={formsOpen}
              disabled={disabled}
              className="w-full min-w-0 justify-between gap-2 border-gray-300 bg-white shadow-xs"
            >
              <span className="truncate text-left">
                {value.questionnaire
                  ? value.questionnaireTitle ||
                    t("location_response_selected_form")
                  : t("location_response_all_forms")}
              </span>
              <ChevronDown className="size-4 shrink-0 text-gray-500" />
            </Button>
          </PopoverTrigger>
          <PopoverContent
            align="start"
            className="w-[min(24rem,calc(100vw-2rem))] p-0"
          >
            <Command shouldFilter={false}>
              <CommandInput
                aria-label={t("search_forms")}
                placeholder={t("search_forms")}
                value={formSearch}
                onValueChange={setFormSearch}
                className="border-none text-base shadow-none ring-0 outline-hidden sm:text-sm"
              />
              <CommandList>
                <CommandGroup>
                  <CommandItem
                    value="all-forms"
                    onSelect={() => {
                      onChange({
                        questionnaire: undefined,
                        questionnaireTitle: undefined,
                      });
                      setFormsOpen(false);
                    }}
                    className="min-h-10"
                  >
                    {t("location_response_all_forms")}
                    {!value.questionnaire && (
                      <Check className="ml-auto size-4" />
                    )}
                  </CommandItem>
                </CommandGroup>
                <CommandSeparator />
                {questionnairesQuery.isLoading ? (
                  <div
                    role="status"
                    className="flex items-center justify-center gap-2 p-6 text-sm text-gray-500"
                  >
                    <Loader2 className="size-4 animate-spin" />
                    {t("loading")}
                  </div>
                ) : questionnairesQuery.isError ? (
                  <div
                    role="alert"
                    className="space-y-3 p-4 text-sm text-gray-600"
                  >
                    <p>{t("questionnaire_error_loading")}</p>
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={questionnairesQuery.isFetching}
                      onClick={() => void questionnairesQuery.refetch()}
                    >
                      {t("try_again")}
                    </Button>
                  </div>
                ) : questionnaires.length === 0 ? (
                  <p className="p-6 text-center text-sm text-gray-500">
                    {t("no_results_found")}
                  </p>
                ) : (
                  <CommandGroup>
                    {questionnaires.map((questionnaire) => (
                      <CommandItem
                        key={questionnaire.id}
                        value={questionnaire.id}
                        onSelect={() => {
                          onChange({
                            questionnaire: questionnaire.id,
                            questionnaireTitle: questionnaire.title,
                          });
                          setFormsOpen(false);
                        }}
                        className="min-h-10 items-start"
                      >
                        <span className="min-w-0 flex-1 break-words">
                          {questionnaire.title}
                        </span>
                        {value.questionnaire === questionnaire.id && (
                          <Check className="mt-0.5 size-4 shrink-0" />
                        )}
                      </CommandItem>
                    ))}
                    {questionnairesQuery.hasNextPage && (
                      <CommandItem
                        value="load-more-forms"
                        disabled={questionnairesQuery.isFetchingNextPage}
                        onSelect={() =>
                          void questionnairesQuery.fetchNextPage()
                        }
                        className="min-h-10 justify-center text-primary-700"
                      >
                        {questionnairesQuery.isFetchingNextPage
                          ? t("loading")
                          : t("load_more")}
                      </CommandItem>
                    )}
                  </CommandGroup>
                )}
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>
      </div>

      <div className="min-w-0 space-y-1.5">
        <Label htmlFor={`${id}-submitted-by`} className="text-xs text-gray-600">
          {t("submitted_by")}
        </Label>
        <UserSelector
          facilityId={facilityId}
          selected={
            selectedUser?.id === value.createdBy ? selectedUser : undefined
          }
          disabled={disabled}
          onChange={(user) => {
            setSelectedUser(user);
            onChange({ createdBy: user.id, creatorName: formatName(user) });
          }}
          onClear={() =>
            onChange({ createdBy: undefined, creatorName: undefined })
          }
          trigger={
            <Button
              id={`${id}-submitted-by`}
              type="button"
              variant="outline"
              role="combobox"
              aria-label={t("submitted_by")}
              disabled={disabled}
              className="w-full min-w-0 justify-between gap-2 border-gray-300 bg-white shadow-xs"
            >
              <span className="truncate text-left">
                {value.createdBy
                  ? value.creatorName ||
                    t("location_response_selected_submitter")
                  : t("location_response_any_submitter")}
              </span>
              <ChevronDown className="size-4 shrink-0 text-gray-500" />
            </Button>
          }
        />
      </div>

      <div className="min-w-0 space-y-1.5">
        <Label htmlFor={`${id}-status`} className="text-xs text-gray-600">
          {t("status")}
        </Label>
        <Select
          value={value.status ?? "all"}
          disabled={disabled}
          onValueChange={(status) =>
            onChange({
              status:
                status === QuestionnaireResponseStatus.Completed
                  ? QuestionnaireResponseStatus.Completed
                  : status === QuestionnaireResponseStatus.EnteredInError
                    ? QuestionnaireResponseStatus.EnteredInError
                    : undefined,
            })
          }
        >
          <SelectTrigger
            id={`${id}-status`}
            aria-label={t("status")}
            className="w-full"
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">{t("all_statuses")}</SelectItem>
            <SelectItem value={QuestionnaireResponseStatus.Completed}>
              {t("completed")}
            </SelectItem>
            <SelectItem value={QuestionnaireResponseStatus.EnteredInError}>
              {t("entered_in_error")}
            </SelectItem>
          </SelectContent>
        </Select>
      </div>

      <Button
        variant="ghost"
        disabled={disabled || !hasFilters}
        onClick={() =>
          onChange({
            questionnaire: undefined,
            questionnaireTitle: undefined,
            createdBy: undefined,
            creatorName: undefined,
            status: undefined,
          })
        }
        className="justify-center gap-1.5 text-gray-600"
      >
        <X className="size-4" />
        {t("clear_filters")}
      </Button>
    </div>
  );
}
import {
  AlertCircle,
  ArrowLeft,
  ArrowRight,
  Link2,
  MapPin,
  X,
} from "lucide-react";
import { useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Skeleton } from "@/components/ui/skeleton";

import { useIsMobile } from "@/hooks/use-mobile";

import { formatDateTime, formatName } from "@/Utils/utils";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import { ResourceQuestionnaireResponse } from "@/types/questionnaire/resourceQuestionnaireResponseApi";

import LocationResponseDetails from "./LocationResponseDetails";

interface LocationResponseViewerProps {
  response: ResourceQuestionnaireResponse | null;
  open: boolean;
  onClose: () => void;
  locationName?: string;
  onPrevious?: () => void;
  onNext?: () => void;
  position?: number;
  total?: number;
  isLoading?: boolean;
  error?: boolean;
  onRetry?: () => void;
  onCopyLink?: () => void;
}

export default function LocationResponseViewer({
  response,
  open,
  onClose,
  locationName,
  onPrevious,
  onNext,
  position,
  total,
  isLoading,
  error,
  onRetry,
  onCopyLink,
}: LocationResponseViewerProps) {
  const { t } = useTranslation();
  const isMobile = useIsMobile();
  const openerRef = useRef<HTMLElement | null>(null);
  const showNavigation = position !== undefined && total !== undefined;

  return (
    <Sheet
      open={open}
      modal={isMobile}
      onOpenChange={(nextOpen) => {
        if (!nextOpen) onClose();
      }}
    >
      <SheetContent
        side="right"
        className="flex h-dvh w-full flex-col gap-0 border-gray-200 p-0 shadow-2xl sm:max-w-none md:w-[min(720px,70vw)] [&>button]:hidden"
        onOpenAutoFocus={() => {
          openerRef.current =
            document.activeElement instanceof HTMLElement
              ? document.activeElement
              : null;
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          if (openerRef.current?.isConnected) openerRef.current.focus();
        }}
        onInteractOutside={(event) => {
          if (!isMobile) event.preventDefault();
        }}
      >
        <SheetHeader className="shrink-0 space-y-0 border-b border-gray-200 bg-white px-5 pb-5 pt-3 text-left sm:px-6">
          <div className="mb-3 flex items-center justify-between gap-3">
            <p className="text-xs font-semibold text-gray-500">
              {t("response_details")}
            </p>
            <div className="flex items-center gap-1">
              {onCopyLink && (
                <Button
                  variant="ghost"
                  className="h-11 px-3 text-gray-600"
                  onClick={onCopyLink}
                >
                  <Link2 className="size-4" />
                  {t("copy_link")}
                </Button>
              )}
              <SheetClose asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-11 text-gray-600"
                  aria-label={t("close")}
                >
                  <X className="size-5" />
                </Button>
              </SheetClose>
            </div>
          </div>
          <SheetTitle className="break-words text-xl leading-7">
            {response?.questionnaire.title || t("view_response")}
          </SheetTitle>
          <SheetDescription className="sr-only">
            {t("response_details")}
          </SheetDescription>
          {(locationName || response) && (
            <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-2">
              {locationName && (
                <span className="inline-flex min-w-0 items-center gap-1.5 text-sm text-gray-600">
                  <MapPin className="size-3.5 shrink-0" />
                  <span className="break-words">{locationName}</span>
                </span>
              )}
              {response && (
                <Badge
                  size="xs"
                  variant={
                    response.status ===
                    QuestionnaireResponseStatus.EnteredInError
                      ? "destructive"
                      : "green"
                  }
                >
                  {t(response.status)}
                </Badge>
              )}
            </div>
          )}
        </SheetHeader>

        <div
          key={response?.id}
          className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-6 sm:px-6"
          data-cy="location-response-content"
          aria-busy={isLoading}
        >
          {isLoading ? (
            <div role="status" className="space-y-6">
              <span className="sr-only">{t("loading")}</span>
              <Skeleton className="h-20 w-full" />
              {[0, 1, 2, 3].map((index) => (
                <div key={index} className="space-y-3">
                  <Skeleton className="h-4 w-1/3" />
                  <Skeleton className="h-6 w-3/4" />
                </div>
              ))}
            </div>
          ) : error || !response ? (
            <Alert variant="destructive">
              <AlertCircle />
              <AlertDescription>
                <p>{t("error_loading_questionnaire_response")}</p>
                {onRetry && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="mt-3"
                    onClick={onRetry}
                  >
                    {t("try_again")}
                  </Button>
                )}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="space-y-7">
              <dl className="grid grid-cols-1 gap-4 rounded-lg border border-gray-200 bg-gray-50 p-4 text-sm sm:grid-cols-2">
                <div>
                  <dt className="text-xs text-gray-500">{t("submitted_by")}</dt>
                  <dd className="mt-1 break-words font-medium text-gray-900">
                    {formatName(response.created_by)}
                  </dd>
                </div>
                <div>
                  <dt className="text-xs text-gray-500">{t("submitted_on")}</dt>
                  <dd className="mt-1 font-medium text-gray-900">
                    {response.created_date
                      ? formatDateTime(response.created_date)
                      : t("unknown")}
                  </dd>
                </div>
              </dl>

              {response.questionnaire.description && (
                <p className="break-words whitespace-pre-wrap text-sm leading-6 text-gray-600">
                  {response.questionnaire.description}
                </p>
              )}

              <section className="space-y-4">
                <h3 className="text-xs font-semibold text-gray-500">
                  {t("submitted_answers")}
                </h3>
                <LocationResponseDetails response={response} />
              </section>
            </div>
          )}
        </div>

        {showNavigation && (
          <div className="shrink-0 border-t border-gray-200 bg-white px-5 py-4 sm:px-6">
            <p
              className="mb-3 text-center text-xs text-gray-500"
              aria-live="polite"
            >
              {t("response_position", { position, total })}
            </p>
            <div className="flex items-center justify-between gap-3">
              <Button
                variant="outline"
                className="h-11 flex-1 border-gray-300 shadow-xs sm:flex-none"
                aria-label={t("previous_response")}
                disabled={!onPrevious || isLoading}
                onClick={onPrevious}
              >
                <ArrowLeft className="size-4" />
                <span className="sm:hidden">{t("previous")}</span>
                <span className="hidden sm:inline">
                  {t("previous_response")}
                </span>
              </Button>
              <Button
                variant="outline"
                className="h-11 flex-1 border-gray-300 shadow-xs sm:flex-none"
                aria-label={t("next_response")}
                disabled={!onNext || isLoading}
                onClick={onNext}
              >
                <span className="sm:hidden">{t("next")}</span>
                <span className="hidden sm:inline">{t("next_response")}</span>
                <ArrowRight className="size-4" />
              </Button>
            </div>
          </div>
        )}
      </SheetContent>
    </Sheet>
  );
}

