import {
  AlertCircle,
  ArrowLeft,
  ArrowRight,
  Link2,
  MapPin,
  X,
} from "lucide-react";
import { useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Skeleton } from "@/components/ui/skeleton";

import { useIsMobile } from "@/hooks/use-mobile";

import { formatDateTime, formatName } from "@/Utils/utils";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import { ResourceQuestionnaireResponse } from "@/types/questionnaire/resourceQuestionnaireResponseApi";

import LocationResponseDetails from "./LocationResponseDetails";

interface LocationResponseViewerProps {
  response: ResourceQuestionnaireResponse | null;
  open: boolean;
  onClose: () => void;
  locationName?: string;
  onPrevious?: () => void;
  onNext?: () => void;
  position?: number;
  total?: number;
  isLoading?: boolean;
  error?: boolean;
  onRetry?: () => void;
  onCopyLink?: () => void;
}

export default function LocationResponseViewer({
  response,
  open,
  onClose,
  locationName,
  onPrevious,
  onNext,
  position,
  total,
  isLoading,
  error,
  onRetry,
  onCopyLink,
}: LocationResponseViewerProps) {
  const { t } = useTranslation();
  const isMobile = useIsMobile();
  const openerRef = useRef<HTMLElement | null>(null);
  const showNavigation = position !== undefined && total !== undefined;

  return (
    <Sheet
      open={open}
      modal={isMobile}
      onOpenChange={(nextOpen) => {
        if (!nextOpen) onClose();
      }}
    >
      <SheetContent
        side="right"
        className="flex h-dvh w-full flex-col gap-0 border-gray-200 p-0 shadow-2xl sm:max-w-none md:w-[min(720px,70vw)] [&>button]:hidden"
        onOpenAutoFocus={() => {
          openerRef.current =
            document.activeElement instanceof HTMLElement
              ? document.activeElement
              : null;
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          if (openerRef.current?.isConnected) openerRef.current.focus();
        }}
        onInteractOutside={(event) => {
          if (!isMobile) event.preventDefault();
        }}
      >
        <SheetHeader className="shrink-0 space-y-0 border-b border-gray-200 bg-white px-5 pb-5 pt-3 text-left sm:px-6">
          <div className="mb-3 flex items-center justify-between gap-3">
            <p className="text-xs font-semibold text-gray-500">
              {t("response_details")}
            </p>
            <div className="flex items-center gap-1">
              {onCopyLink && (
                <Button
                  variant="ghost"
                  className="h-11 px-3 text-gray-600"
                  onClick={onCopyLink}
                >
                  <Link2 className="size-4" />
                  {t("copy_link")}
                </Button>
              )}
              <SheetClose asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-11 text-gray-600"
                  aria-label={t("close")}
                >
                  <X className="size-5" />
                </Button>
              </SheetClose>
            </div>
          </div>
          <SheetTitle className="break-words text-xl leading-7">
            {response?.questionnaire.title || t("view_response")}
          </SheetTitle>
          <SheetDescription className="sr-only">
            {t("response_details")}
          </SheetDescription>
          {(locationName || response) && (
            <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-2">
              {locationName && (
                <span className="inline-flex min-w-0 items-center gap-1.5 text-sm text-gray-600">
                  <MapPin className="size-3.5 shrink-0" />
                  <span className="break-words">{locationName}</span>
                </span>
              )}
              {response && (
                <Badge
                  size="xs"
                  variant={
                    response.status ===
                    QuestionnaireResponseStatus.EnteredInError
                      ? "destructive"
                      : "green"
                  }
                >
                  {t(response.status)}
                </Badge>
              )}
            </div>
          )}
        </SheetHeader>

        <div
          key={response?.id}
          className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-6 sm:px-6"
          data-cy="location-response-content"
          aria-busy={isLoading}
        >
          {isLoading ? (
            <div role="status" className="space-y-6">
              <span className="sr-only">{t("loading")}</span>
              <Skeleton className="h-20 w-full" />
              {[0, 1, 2, 3].map((index) => (
                <div key={index} className="space-y-3">
                  <Skeleton className="h-4 w-1/3" />
                  <Skeleton className="h-6 w-3/4" />
                </div>
              ))}
            </div>
          ) : error || !response ? (
            <Alert variant="destructive">
              <AlertCircle />
              <AlertDescription>
                <p>{t("error_loading_questionnaire_response")}</p>
                {onRetry && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="mt-3"
                    onClick={onRetry}
                  >
                    {t("try_again")}
                  </Button>
                )}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="space-y-7">
              <dl className="grid grid-cols-1 gap-4 rounded-lg border border-gray-200 bg-gray-50 p-4 text-sm sm:grid-cols-2">
                <div>
                  <dt className="text-xs text-gray-500">{t("submitted_by")}</dt>
                  <dd className="mt-1 break-words font-medium text-gray-900">
                    {formatName(response.created_by)}
                  </dd>
                </div>
                <div>
                  <dt className="text-xs text-gray-500">{t("submitted_on")}</dt>
                  <dd className="mt-1 font-medium text-gray-900">
                    {response.created_date
                      ? formatDateTime(response.created_date)
                      : t("unknown")}
                  </dd>
                </div>
              </dl>

              {response.questionnaire.description && (
                <p className="break-words whitespace-pre-wrap text-sm leading-6 text-gray-600">
                  {response.questionnaire.description}
                </p>
              )}

              <section className="space-y-4">
                <h3 className="text-xs font-semibold text-gray-500">
                  {t("submitted_answers")}
                </h3>
                <LocationResponseDetails response={response} />
              </section>
            </div>
          )}
        </div>

        {showNavigation && (
          <div className="shrink-0 border-t border-gray-200 bg-white px-5 py-4 sm:px-6">
            <p
              className="mb-3 text-center text-xs text-gray-500"
              aria-live="polite"
            >
              {t("response_position", { position, total })}
            </p>
            <div className="flex items-center justify-between gap-3">
              <Button
                variant="outline"
                className="h-11 flex-1 border-gray-300 shadow-xs sm:flex-none"
                aria-label={t("previous_response")}
                disabled={!onPrevious || isLoading}
                onClick={onPrevious}
              >
                <ArrowLeft className="size-4" />
                <span className="sm:hidden">{t("previous")}</span>
                <span className="hidden sm:inline">
                  {t("previous_response")}
                </span>
              </Button>
              <Button
                variant="outline"
                className="h-11 flex-1 border-gray-300 shadow-xs sm:flex-none"
                aria-label={t("next_response")}
                disabled={!onNext || isLoading}
                onClick={onNext}
              >
                <span className="sm:hidden">{t("next")}</span>
                <span className="hidden sm:inline">{t("next_response")}</span>
                <ArrowRight className="size-4" />
              </Button>
            </div>
          </div>
        )}
      </SheetContent>
    </Sheet>
  );
}

