import { useInfiniteQuery } from "@tanstack/react-query";
import { Check, ChevronDown, Loader2, X } from "lucide-react";
import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  Command,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import UserSelector from "@/components/Common/UserSelector";
import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import query from "@/Utils/request/query";
import { formatName } from "@/Utils/utils";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import { UserReadMinimal } from "@/types/user/user";

export interface LocationResponseFilterValues {
  questionnaire?: string;
  questionnaireTitle?: string;
  createdBy?: string;
  creatorName?: string;
  status?: QuestionnaireResponseStatus;
}

interface LocationResponseFiltersProps {
  facilityId: string;
  value: LocationResponseFilterValues;
  onChange: (patch: Partial<LocationResponseFilterValues>) => void;
  disabled?: boolean;
}

const QUESTIONNAIRES_PER_PAGE = 30;

export default function LocationResponseFilters({
  facilityId,
  value,
  onChange,
  disabled = false,
}: LocationResponseFiltersProps) {
  const { t } = useTranslation();
  const id = useId();
  const [formsOpen, setFormsOpen] = useState(false);
  const [formSearch, setFormSearch] = useState("");
  const [selectedUser, setSelectedUser] = useState<UserReadMinimal>();

  const questionnairesQuery = useInfiniteQuery({
    queryKey: [
      ...questionnaireKeys.all,
      "location-response-filter",
      facilityId,
      formSearch,
    ],
    queryFn: ({ pageParam, signal }) =>
      query.debounced(questionnaireApi.list, {
        queryParams: {
          subject_type: "location",
          facility_or_instance: facilityId,
          title: formSearch || undefined,
          limit: QUESTIONNAIRES_PER_PAGE,
          offset: pageParam,
        },
      })({ signal }),
    initialPageParam: 0,
    getNextPageParam: (lastPage, pages) => {
      const offset = pages.length * QUESTIONNAIRES_PER_PAGE;
      return offset < lastPage.count ? offset : undefined;
    },
    enabled: formsOpen && !disabled,
  });

  const questionnaires =
    questionnairesQuery.data?.pages.flatMap((page) => page.results) ?? [];
  const hasFilters = !!(value.questionnaire || value.createdBy || value.status);

  return (
    <div
      role="group"
      aria-label={t("location_response_filter_label")}
      data-cy="location-response-filters"
      className="grid grid-cols-1 items-end gap-3 bg-gray-50 p-4 sm:grid-cols-2 lg:grid-cols-[minmax(0,1.35fr)_minmax(0,1fr)_minmax(0,0.85fr)_auto]"
    >
      <div className="min-w-0 space-y-1.5">
        <Label
          htmlFor={`${id}-questionnaire`}
          className="text-xs text-gray-600"
        >
          {t("questionnaire")}
        </Label>
        <Popover
          open={formsOpen}
          onOpenChange={(open) => {
            setFormsOpen(open);
            if (open) setFormSearch("");
          }}
        >
          <PopoverTrigger asChild>
            <Button
              id={`${id}-questionnaire`}
              type="button"
              variant="outline"
              role="combobox"
              aria-label={t("questionnaire")}
              aria-expanded={formsOpen}
              disabled={disabled}
              className="w-full min-w-0 justify-between gap-2 border-gray-300 bg-white shadow-xs"
            >
              <span className="truncate text-left">
                {value.questionnaire
                  ? value.questionnaireTitle ||
                    t("location_response_selected_form")
                  : t("location_response_all_forms")}
              </span>
              <ChevronDown className="size-4 shrink-0 text-gray-500" />
            </Button>
          </PopoverTrigger>
          <PopoverContent
            align="start"
            className="w-[min(24rem,calc(100vw-2rem))] p-0"
          >
            <Command shouldFilter={false}>
              <CommandInput
                aria-label={t("search_forms")}
                placeholder={t("search_forms")}
                value={formSearch}
                onValueChange={setFormSearch}
                className="border-none text-base shadow-none ring-0 outline-hidden sm:text-sm"
              />
              <CommandList>
                <CommandGroup>
                  <CommandItem
                    value="all-forms"
                    onSelect={() => {
                      onChange({
                        questionnaire: undefined,
                        questionnaireTitle: undefined,
                      });
                      setFormsOpen(false);
                    }}
                    className="min-h-10"
                  >
                    {t("location_response_all_forms")}
                    {!value.questionnaire && (
                      <Check className="ml-auto size-4" />
                    )}
                  </CommandItem>
                </CommandGroup>
                <CommandSeparator />
                {questionnairesQuery.isLoading ? (
                  <div
                    role="status"
                    className="flex items-center justify-center gap-2 p-6 text-sm text-gray-500"
                  >
                    <Loader2 className="size-4 animate-spin" />
                    {t("loading")}
                  </div>
                ) : questionnairesQuery.isError ? (
                  <div
                    role="alert"
                    className="space-y-3 p-4 text-sm text-gray-600"
                  >
                    <p>{t("questionnaire_error_loading")}</p>
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={questionnairesQuery.isFetching}
                      onClick={() => void questionnairesQuery.refetch()}
                    >
                      {t("try_again")}
                    </Button>
                  </div>
                ) : questionnaires.length === 0 ? (
                  <p className="p-6 text-center text-sm text-gray-500">
                    {t("no_results_found")}
                  </p>
                ) : (
                  <CommandGroup>
                    {questionnaires.map((questionnaire) => (
                      <CommandItem
                        key={questionnaire.id}
                        value={questionnaire.id}
                        onSelect={() => {
                          onChange({
                            questionnaire: questionnaire.id,
                            questionnaireTitle: questionnaire.title,
                          });
                          setFormsOpen(false);
                        }}
                        className="min-h-10 items-start"
                      >
                        <span className="min-w-0 flex-1 break-words">
                          {questionnaire.title}
                        </span>
                        {value.questionnaire === questionnaire.id && (
                          <Check className="mt-0.5 size-4 shrink-0" />
                        )}
                      </CommandItem>
                    ))}
                    {questionnairesQuery.hasNextPage && (
                      <CommandItem
                        value="load-more-forms"
                        disabled={questionnairesQuery.isFetchingNextPage}
                        onSelect={() =>
                          void questionnairesQuery.fetchNextPage()
                        }
                        className="min-h-10 justify-center text-primary-700"
                      >
                        {questionnairesQuery.isFetchingNextPage
                          ? t("loading")
                          : t("load_more")}
                      </CommandItem>
                    )}
                  </CommandGroup>
                )}
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>
      </div>

      <div className="min-w-0 space-y-1.5">
        <Label htmlFor={`${id}-submitted-by`} className="text-xs text-gray-600">
          {t("submitted_by")}
        </Label>
        <UserSelector
          facilityId={facilityId}
          selected={
            selectedUser?.id === value.createdBy ? selectedUser : undefined
          }
          disabled={disabled}
          onChange={(user) => {
            setSelectedUser(user);
            onChange({ createdBy: user.id, creatorName: formatName(user) });
          }}
          onClear={() =>
            onChange({ createdBy: undefined, creatorName: undefined })
          }
          trigger={
            <Button
              id={`${id}-submitted-by`}
              type="button"
              variant="outline"
              role="combobox"
              aria-label={t("submitted_by")}
              disabled={disabled}
              className="w-full min-w-0 justify-between gap-2 border-gray-300 bg-white shadow-xs"
            >
              <span className="truncate text-left">
                {value.createdBy
                  ? value.creatorName ||
                    t("location_response_selected_submitter")
                  : t("location_response_any_submitter")}
              </span>
              <ChevronDown className="size-4 shrink-0 text-gray-500" />
            </Button>
          }
        />
      </div>

      <div className="min-w-0 space-y-1.5">
        <Label htmlFor={`${id}-status`} className="text-xs text-gray-600">
          {t("status")}
        </Label>
        <Select
          value={value.status ?? "all"}
          disabled={disabled}
          onValueChange={(status) =>
            onChange({
              status:
                status === QuestionnaireResponseStatus.Completed
                  ? QuestionnaireResponseStatus.Completed
                  : status === QuestionnaireResponseStatus.EnteredInError
                    ? QuestionnaireResponseStatus.EnteredInError
                    : undefined,
            })
          }
        >
          <SelectTrigger
            id={`${id}-status`}
            aria-label={t("status")}
            className="w-full"
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">{t("all_statuses")}</SelectItem>
            <SelectItem value={QuestionnaireResponseStatus.Completed}>
              {t("completed")}
            </SelectItem>
            <SelectItem value={QuestionnaireResponseStatus.EnteredInError}>
              {t("entered_in_error")}
            </SelectItem>
          </SelectContent>
        </Select>
      </div>

      <Button
        variant="ghost"
        disabled={disabled || !hasFilters}
        onClick={() =>
          onChange({
            questionnaire: undefined,
            questionnaireTitle: undefined,
            createdBy: undefined,
            creatorName: undefined,
            status: undefined,
          })
        }
        className="justify-center gap-1.5 text-gray-600"
      >
        <X className="size-4" />
        {t("clear_filters")}
      </Button>
    </div>
  );
}
