{"status":"fulfilled","value":{"chunk_id":"70acec","wall_time_seconds":0.000002792,"exit_code":1,"original_token_count":4234,"output":"export const INNER_PAGE_02_CODE = `import React, { useCallback, useEffect, useRef, useState } from "react"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  useSidebar,
} from "@/components/ui/sidebar"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Separator } from "@/components/ui/separator"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  Bell, CalendarDays, ChevronLeft, ChevronsUpDown,
  ClipboardList, Clock, Package, PanelLeft, Syringe, Users, X,
} from "lucide-react"
import { prepareWithSegments, measureNaturalWidth } from "@chenglou/pretext"

// ─── Middle truncation ────────────────────────────────────────────────────────

function truncateMiddle(text: string, font: string, maxWidth: number): string {
  const measure = (t: string) =>
    t ? measureNaturalWidth(prepareWithSegments(t, font)) : 0
  if (measure(text) <= maxWidth) return text
  const ELLIPSIS = "\u2026"
  const ellipsisW = measure(ELLIPSIS)
  const available = maxWidth - ellipsisW
  if (available <= 0) return ELLIPSIS
  let lo = 0
  let hi = Math.floor(text.length / 2)
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2)
    if (measure(text.slice(0, mid) + text.slice(text.length - mid)) <= available) {
      lo = mid
    } else {
      hi = mid - 1
    }
  }
  return text.slice(0, lo) + ELLIPSIS + text.slice(text.length - lo)
}

// ─── Navigation data ──────────────────────────────────────────────────────────

const locations = [
  "Pharmacy - Ground Floor",
  "ICU - Floor 2",
  "OPD - Block A",
  "Ward B",
]

const pharmacyItems = [
  { title: "Prescription Queue", icon: ClipboardList, isActive: true },
  { title: "Dispense Medicine",  icon: Syringe },
  { title: "Inventory",          icon: Package },
]

const patientItems = [
  { title: "Schedule",     icon: Clock },
  { title: "Appointments", icon: CalendarDays },
  { title: "Queues",       icon: Users },
]

// ─── Location selector ────────────────────────────────────────────────────────

function LocationSelector({ onOpenChange }: { onOpenChange?: (open: boolean) => void }) {
  const [selected, setSelected] = useState(locations[0])
  const labelRef = useRef<HTMLParagraphElement>(null)
  const [displayName, setDisplayName] = useState(selected)

  useEffect(() => {
    const el = labelRef.current
    if (!el) return
    const update = () => {
      const w = el.offsetWidth
      if (w === 0) return
      setDisplayName(truncateMiddle(selected, getComputedStyle(el).font, w))
    }
    update()
    const ro = new ResizeObserver(update)
    ro.observe(el)
    return () => ro.disconnect()
  }, [selected])

  const isTruncated = displayName !== selected

  return (
    <Tooltip>
      <DropdownMenu onOpenChange={onOpenChange}>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <button className="flex w-full items-center justify-between rounded-lg border bg-background px-3 py-2.5 text-left transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
              <div className="min-w-0 flex-1">
                <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Chosen Location
                </p>
                <p ref={labelRef} className="text-sm font-semibold overflow-hidden whitespace-nowrap">
                  {displayName}
                </p>
              </div>
              <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 text-muted-foreground" />
            </button>
          </DropdownMenuTrigger>
        </TooltipTrigger>
        {isTruncated && (
          <TooltipContent side="bottom">{selected}</TooltipContent>
        )}
        <DropdownMenuContent align="start" className="w-56">
          <DropdownMenuRadioGroup value={selected} onValueChange={setSelected}>
            {locations.map((loc) => (
              <DropdownMenuRadioItem key={loc} value={loc}>
                {loc}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    </Tooltip>
  )
}

// ─── Inner sidebar ────────────────────────────────────────────────────────────

function InnerSidebarContent({ pinned, onMenuOpenChange }: { pinned: boolean; onMenuOpenChange?: (open: boolean) => void }) {
  const { isMobile, setOpenMobile } = useSidebar()
  const showBackRow = pinned || isMobile
  return (
    <>
      <SidebarHeader className="border-b">
        <div className="space-y-2 px-2 py-2">
          <div className={"flex items-center overflow-hidden transition-opacity duration-150 ease-linear " + (showBackRow ? "h-8 opacity-100" : "h-0 opacity-0 pointer-events-none")}>
            <Button variant="ghost" size="sm" className="gap-1.5 text-muted-foreground hover:text-foreground -ml-1">
              <ChevronLeft className="h-4 w-4" />
              Back
            </Button>
            {isMobile && (
              <Button variant="ghost" size="icon" className="ml-auto" onClick={() => setOpenMobile(false)}>
                <X className="h-4 w-4" />
                <span className="sr-only">Close sidebar</span>
              </Button>
            )}
          </div>
          <LocationSelector onOpenChange={onMenuOpenChange} />
        </div>
      </SidebarHeader>
      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupLabel>Pharmacy</SidebarGroupLabel>
          <SidebarMenu>
            {pharmacyItems.map((item) => (
              <SidebarMenuItem key={item.title}>
                <SidebarMenuButton isActive={item.isActive} tooltip={item.title}>
                  <item.icon />
                  <span>{item.title}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            ))}
          </SidebarMenu>
        </SidebarGroup>
        <Separator className="mx-3 my-1 w-auto" />
        <SidebarGroup>
          <SidebarGroupLabel>Patient Management</SidebarGroupLabel>
          <SidebarMenu>
            {patientItems.map((item) => (
              <SidebarMenuItem key={item.title}>
                <SidebarMenuButton tooltip={item.title}>
                  <item.icon />
                  <span>{item.title}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            ))}
          </SidebarMenu>
        </SidebarGroup>
      </SidebarContent>
    </>
  )
}

// ─── Inner page header ────────────────────────────────────────────────────────

function InnerPageHeader({ pinned, cancelClose, scheduleClose, setOverlayReady, setOverlayOpen, toggleSidebar }: {
  pinned: boolean
  cancelClose: () => void
  scheduleClose: () => void
  setOverlayReady: (v: boolean) => void
  setOverlayOpen: (v: boolean) => void
  toggleSidebar: () => void
}) {
  const { isMobile, setOpenMobile } = useSidebar()
  const showBack = !pinned && !isMobile
  return (
    <header className="flex h-12 shrink-0 items-center gap-3 border-b bg-background px-4">
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onMouseEnter={() => { cancelClose(); if (!pinned) { setOverlayReady(true); setOverlayOpen(true) } }}
            onMouseLeave={scheduleClose}
            onClick={() => isMobile ? setOpenMobile(true) : toggleSidebar()}
          >
            <PanelLeft className="h-4 w-4" />
          </Button>
        </TooltipTrigger>
        <TooltipContent side="right">Toggle sidebar</TooltipContent>
      </Tooltip>
      {showBack && (
        <>
          <Separator orientation="vertical" />
          <Button variant="ghost" size="sm" className="gap-1.5 text-muted-foreground hover:text-foreground">
            <ChevronLeft className="h-4 w-4" />
            Back
          </Button>
        </>
      )}
      <Separator orientation="vertical" />
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink>Patients</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>John Doe</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>
      <div className="ml-auto flex items-center gap-2">
        <Button variant="outline" size="icon-sm">
          <Bell className="h-3.5 w-3.5" />
          <span className="sr-only">Alerts</span>
        </Button>
      </div>
    </header>
  )
}

// ─── Layout ───────────────────────────────────────────────────────────────────

export function InnerPageLayout() {
  const [pinned, setPinned] = useState(true)
  const [overlayOpen, setOverlayOpen] = useState(false)
  const [overlayReady, setOverlayReady] = useState(false)
  const [pinningTransition, setPinningTransition] = useState(false)
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const settleTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const menuOpenRef = useRef(false)

  const cancelClose = useCallback(() => {
    clearTimeout(closeTimer.current ?? undefined)
    clearTimeout(settleTimer.current ?? undefined)
    closeTimer.current = null
    settleTimer.current = null
  }, [])

import React from "react";
import { Button } from "@/components/ui/button";
import { Kbd } from "@/components/ui/kbd";
import { Separator } from "@/components/ui/separator";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { useSidebar } from "@/components/ui/sidebar";
import { ChevronLeft, PanelLeft } from "lucide-react";

// ─── usePinnableSidebar ───────────────────────────────────────────────────────
//
// Encapsulates the pinned/overlay state machine shared by all sidebar block
// demos. Handles hover-to-peek, pin/unpin toggling, and the settle delay that
// prevents the overlay container from snapping while the slide-out animation
// is still in progress.

interface UsePinnableSidebarReturn {
  pinned: boolean;
  overlayOpen: boolean;
  overlayReady: boolean;
  pinningTransition: boolean;
  isOverlay: boolean;
  menuOpenRef: React.MutableRefObject<boolean>;
  cancelClose: () => void;
  scheduleClose: () => void;
  handleToggleMouseEnter: () => void;
  handleMenuOpenChange: (open: boolean) => void;
  handleSidebarProviderOpenChange: (open: boolean) => void;
  toggleSidebar: () => void;
}

export function usePinnableSidebar(): UsePinnableSidebarReturn {
  const [pinned, setPinned] = React.useState(true);
  const [overlayOpen, setOverlayOpen] = React.useState(false);
  // overlayReady becomes true only AFTER the close animation finishes (~210ms).
  // This prevents top/height from snapping while the sidebar is still visible.
  const [overlayReady, setOverlayReady] = React.useState(false);
  const [pinningTransition, setPinningTransition] = React.useState(false);
  const closeTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null
  );
  const settleTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null
  );
  const menuOpenRef = React.useRef(false);

  const cancelClose = React.useCallback(() => {
    clearTimeout(closeTimerRef.current ?? undefined);
    clearTimeout(settleTimerRef.current ?? undefined);
    closeTimerRef.current = null;
    settleTimerRef.current = null;
  }, []);

  const startSettle = React.useCallback(() => {
    clearTimeout(settleTimerRef.current ?? undefined);
    settleTimerRef.current = setTimeout(() => setOverlayReady(true), 210);
  }, []);

  const scheduleClose = React.useCallback(() => {
    if (!pinned && !menuOpenRef.current) {
      cancelClose();
      closeTimerRef.current = setTimeout(() => {
        setOverlayOpen(false);
        startSettle();
      }, 300);
    }
  }, [pinned, cancelClose, startSettle]);

  const isOverlay = overlayOpen && !pinned;

  const handleToggleMouseEnter = React.useCallback(() => {
    cancelClose();
    if (!pinned) {
      setOverlayReady(true);
      setOverlayOpen(true);
    }
  }, [pinned, cancelClose]);

  const toggleSidebar = React.useCallback(() => {
    cancelClose();
    if (isOverlay) {
      setPinningTransition(true);
      setOverlayReady(false);
      setPinned(true);
      setOverlayOpen(false);
      setTimeout(() => setPinningTransition(false), 200);
    } else if (pinned) {
      setOverlayReady(false);
      setPinned(false);
      setOverlayOpen(false);
      startSettle();
    } else {
      setPinned(true);
      setOverlayOpen(false);
    }
  }, [isOverlay, pinned, cancelClose, startSettle]);

  const handleMenuOpenChange = React.useCallback(
    (open: boolean) => {
      menuOpenRef.current = open;
      if (open) cancelClose();
      else scheduleClose();
    },
    [cancelClose, scheduleClose]
  );

  const handleSidebarProviderOpenChange = React.useCallback(
    (open: boolean) => {
      if (open) {
        setOverlayReady(false);
        setPinned(true);
        setOverlayOpen(false);
      } else {
        setOverlayReady(false);
        setPinned(false);
        setOverlayOpen(false);
        startSettle();
      }
    },
    [startSettle]
  );

  // Clean up pending timers on unmount to avoid state updates on a dead component.
  React.useEffect(() => {
    return () => {
      clearTimeout(closeTimerRef.current ?? undefined);
      clearTimeout(settleTimerRef.current ?? undefined);
    };
  }, []);

  return {
    pinned,
    overlayOpen,
    overlayReady,
    pinningTransition,
    isOverlay,
    menuOpenRef,
    cancelClose,
    scheduleClose,
    handleToggleMouseEnter,
    handleMenuOpenChange,
    handleSidebarProviderOpenChange,
    toggleSidebar,
  };
}

// ─── SidebarToggleButton ──────────────────────────────────────────────────────

export function SidebarToggleButton({
  onDesktopToggle,
  onMouseEnter,
  onMouseLeave,
}: {
  onDesktopToggle: () => void;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
}) {
  const { isMobile, setOpenMobile } = useSidebar();

  const button = (
    <Button
      variant="ghost"
      size="icon"
      className="relative -ml-1 h-7 w-7 after:absolute after:-inset-3 after:content-['']"
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      onClick={() => {
        if (isMobile) {
          setOpenMobile(true);
        } else {
          onDesktopToggle();
        }
      }}
    >
      <PanelLeft className="h-4 w-4" />
      <span className="sr-only">Toggle Sidebar</span>
    </Button>
  );

  if (isMobile) return button;

  return (
    <Tooltip>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <TooltipContent side="left" className="flex items-center gap-1.5">
        Toggle sidebar
        <Kbd>⌘B</Kbd>
      </TooltipContent>
    </Tooltip>
  );
}

// ─── InnerPageBackButton ──────────────────────────────────────────────────────

export function InnerPageBackButton({ pinned }: { pinned: boolean }) {
  const { isMobile } = useSidebar();
  if (pinned && !isMobile) return null;
  return (
    <>
      <Separator orientation="vertical" />
      <Button
        variant="tertiary"
        size="sm"
        className="text-muted-foreground hover:text-foreground gap-1.5"
      >
        <ChevronLeft className="h-4 w-4" />
        Back
      </Button>
    </>
  );
}
