type AsyncButtonState = "idle" | "loading" | "success" | "error";

const BTN_SPRING = { type: "spring" as const, duration: 0.3, bounce: 0 };
const BTN_FADE_UP = {
  initial: { opacity: 0, y: 6 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0 },
  transition: { ...BTN_SPRING, exit: { duration: 0 } },
};
const BTN_FADE_DOWN = {
  initial: { opacity: 0, y: -6 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: 6 },
  transition: BTN_SPRING,
};
const BTN_SNAP_IN = {
  initial: { opacity: 1, y: 0 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -6 },
  transition: BTN_SPRING,
};

type AsyncButtonProps = Omit<React.ComponentProps<typeof Button>, "onClick"> & {
  onClick: () => Promise<void>;
  idleContent: React.ReactNode;
  successContent?: React.ReactNode;
  errorContent?: React.ReactNode;
  disableOnSuccess?: boolean;
};

function AsyncButton({
  onClick,
  idleContent,
  successContent,
  errorContent,
  disableOnSuccess = true,
  variant: variantProp = "default",
  ...props
}: AsyncButtonProps) {
  const [state, setState] = React.useState<AsyncButtonState>("idle");
  const isLoading = state === "loading";
  const isSuccess = state === "success";
  const isError = state === "error";

  async function handleClick() {
    if (isLoading) return;
    setState("loading");
    try {
      await onClick();
      setState("success");
    } catch {
      setState("error");
    }
  }

  const variant = isError ? "destructive" : variantProp;

  return React.createElement(
    Button,
    {
      ...props,
      variant,
      disabled: (disableOnSuccess && isSuccess) || props.disabled,
      onClick: handleClick,
      className:
        "overflow-hidden" +
        (isLoading ? " pointer-events-none" : "") +
        (props.className ? " " + props.className : ""),
    },
    React.createElement(
      "span",
      {
        className:
          "grid *:col-start-1 *:row-start-1 *:flex *:items-center *:justify-center *:gap-1.5",
      },
      // Invisible sizers for every state → width = max(idle, success, error)
      React.createElement(
        "span",
        { className: "invisible", "aria-hidden": "true" },
        idleContent
      ),
      successContent
        ? React.createElement(
            "span",
            { className: "invisible", "aria-hidden": "true" },
            successContent
          )
        : null,
      errorContent
        ? React.createElement(
            "span",
            { className: "invisible", "aria-hidden": "true" },
            errorContent
          )
        : null,
      React.createElement(
        AnimatePresence,
        { mode: "popLayout", initial: false },
        isLoading
          ? React.createElement(
              motion.span,
              { key: "loading", ...BTN_SNAP_IN },
              React.createElement(RadialSpinner, {
                ["data-icon"]: "inline-start",
                className: "text-inherit",
              } as any)
            )
          : isSuccess && successContent
            ? React.createElement(
                motion.span,
                { key: "success", ...BTN_FADE_DOWN },
                successContent
              )
            : isError && errorContent
              ? React.createElement(
                  motion.span,
                  { key: "error", ...BTN_FADE_DOWN },
                  errorContent
                )
              : React.createElement(
                  motion.span,
                  { key: "idle", ...BTN_FADE_UP },
                  idleContent
                )
      )
    )
  );
}

