import { PanelLeft } from "lucide-react";
import { Link, usePath } from "raviger";
import { useTranslation } from "react-i18next";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { Button } from "@/components/ui/button";
import { useSidebar } from "@/components/ui/sidebar";
import { TooltipComponent } from "@/components/ui/tooltip";

import useCurrentLocation from "@/pages/Facility/locations/utils/useCurrentLocation";

export function LocationPageHeader() {
  const { t } = useTranslation();
  const { facilityId, locationId, location } = useCurrentLocation();
  const { toggleSidebar, isMobile, open, openMobile } = useSidebar();
  const path = usePath() ?? "";
  const baseUrl = `/facility/${facilityId}/locations/${locationId}`;
  const section = path.slice(baseUrl.length);
  const pageTitles = [
    ["/responses", t("responses")],
    ["/forms", t("responses")],
    ["/beds", t("beds")],
    ["/service_requests", t("service_requests")],
    ["/medication_requests", t("prescription_queue")],
    ["/medication_dispense", t("dispense")],
    ["/medication_return", t("medication_return")],
    ["/inventory/internal/receive", t("to_receive")],
    ["/inventory/internal/dispatch", t("to_dispatch")],
    ["/inventory/external/orders", t("purchase_orders")],
    ["/inventory/external/deliveries", t("purchase_deliveries")],
    ["/inventory", t("inventory")],
    ["/schedule", t("schedule")],
    ["/appointments", t("appointments")],
    ["/queues", t("queues")],
  ];
  const pageTitle =
    pageTitles.find(([prefix]) => section.startsWith(prefix))?.[1] ??
    t("overview");

  return (
    <header
      data-cy="location-page-header"
      className="sticky top-0 z-10 flex h-12 shrink-0 items-center gap-3 border-b border-neutral-200 bg-white px-4 text-neutral-950"
    >
      <TooltipComponent content={t("toggle_sidebar")}>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label={t("toggle_sidebar")}
          aria-expanded={isMobile ? openMobile : open}
          onClick={toggleSidebar}
          className="relative -ml-1 size-7 shrink-0 rounded-md text-neutral-700 after:absolute after:-inset-2 hover:bg-neutral-200 hover:text-neutral-950 focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2"
        >
          <PanelLeft className="size-4" aria-hidden="true" />
        </Button>
      </TooltipComponent>
      <span aria-hidden="true" className="h-5 w-px bg-neutral-200" />
      <Breadcrumb className="min-w-0">
        <BreadcrumbList className="flex-nowrap text-neutral-600">
          <BreadcrumbItem className="min-w-0">
            <BreadcrumbLink asChild>
              <Link
                basePath="/"
                href={`${baseUrl}/overview`}
                className="truncate rounded-sm underline underline-offset-4 hover:text-neutral-950 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500"
              >
                {location?.name ?? t("location")}
              </Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem className="min-w-0">
            <BreadcrumbPage className="truncate text-neutral-950">
              {pageTitle}
            </BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>
    </header>
  );
}

