function NavItem({
  item,
  setOpen,
  appearance,
}: {
  item: NavigationLink;
  setOpen: (open: boolean) => void;
  appearance: NavAppearance;
}) {
  const path = usePath();
  const selected = path === item.url;
  const isCareUI = appearance === "careui";

  return (
    <NavLink
      href={item.url}
      isSelected={selected}
      isActive={isCareUI ? isNavigationActive(path, item.url) : undefined}
      className={cn(
        "w-full",
        isCareUI
          ? CAREUI_NAV_CLASSES
          : "rounded-md px-2 py-1.5 text-sm outline-none transition-colors hover:bg-gray-100 focus:bg-gray-100",
      )}
      activeClass={isCareUI ? undefined : "bg-gray-100 text-green-700"}
      onClick={() => setOpen(false)}
    >
      {item.name}
    </NavLink>
  );
}

function PopoverMenu({
  link,
  appearance,
}: {
  link: NavigationLink;
  appearance: NavAppearance;
}) {
  const [open, setOpen] = useState(false);
  const path = usePath();
  const isCareUI = appearance === "careui";
  const childActive = isCareUI
    ? !!link.children?.some(
        (child) =>
          child.visibility !== false && isNavigationActive(path, child.url),
      )
    : isChildActive(link);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <SidebarMenuButton
          aria-label={isCareUI ? link.name : undefined}
          tooltip={link.name}
          isActive={isCareUI && childActive}
          className={cn(
            isCareUI
              ? CAREUI_NAV_CLASSES
              : "cursor-pointer hover:bg-gray-200 hover:text-green-700",
            {
              "bg-white text-green-700 shadow": !isCareUI && childActive,
            },
          )}
        >
          {link.icon ? (
            link.icon
          ) : (
            <Avatar name={link.name} className="size-6 -m-1 rounded-sm" />
          )}
        </SidebarMenuButton>
      </PopoverTrigger>
      <PopoverContent
        side="right"
        align="start"
        className={cn(
          "w-48 p-1",
          isCareUI &&
            "w-60 rounded-xl border-neutral-200 bg-white text-neutral-950 shadow-md",
        )}
        aria-label={isCareUI ? link.name : undefined}
        onCloseAutoFocus={isCareUI ? undefined : (e) => e.preventDefault()}
      >
        <div className={cn("flex flex-col", isCareUI ? "gap-0.5" : "gap-1")}>
          {link.children
            ?.filter((item) => !isCareUI || item.visibility !== false)
            .map((subItem) => (
              <NavItem
                key={subItem.name}
                item={subItem}
                setOpen={setOpen}
                appearance={appearance}
              />
            ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import Loading from "@/components/Common/Loading";
import Page from "@/components/Common/Page";

import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import { Code } from "@/types/base/code/code";

export function TaxCodeSettings() {
  const { t } = useTranslation();
  const { facility } = useCurrentFacility();
  const [search, setSearch] = useState("");

  if (!facility) {
    return <Loading />;
  }

  const allCodes = facility.instance_tax_codes || [];

  const filteredCodes = allCodes.filter(
    (code) =>
      code.display.toLowerCase().includes(search.toLowerCase()) ||
      code.code.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <Page
      title={t("tax_codes")}
      options={
        <div className="flex items-center gap-2">
          <Input
            placeholder={t("search_tax_codes")}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-[300px]"
          />
        </div>
      }
    >
      <div className="rounded-md border overflow-hidden mt-4">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{t("name")}</TableHead>
              <TableHead>{t("code")}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody className="bg-white">
            {filteredCodes.length === 0 ? (
              <TableRow>
                <TableCell colSpan={2} className="text-center h-24">
                  {search ? t("no_matching_tax_codes") : t("no_tax_codes")}
                </TableCell>
              </TableRow>
            ) : (
              filteredCodes.map((code: Code) => (
                <TableRow key={code.code}>
                  <TableCell>{code.display}</TableCell>
                  <TableCell>
                    <code className="px-2 py-1 rounded bg-gray-100 text-sm">
                      {code.code}
                    </code>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>
    </Page>
  );
}
