import { FilePlus2 } from "lucide-react";
import { navigate } from "raviger";
import { ReactNode } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { QuestionnaireSearch } from "@/components/Questionnaire/QuestionnaireSearch";

interface LocationFormPickerProps {
  facilityId: string;
  locationId: string;
  trigger?: ReactNode;
  disabled?: boolean;
}

export function LocationFormPicker({
  facilityId,
  locationId,
  trigger,
  disabled = false,
}: LocationFormPickerProps) {
  const { t } = useTranslation();

  return (
    <QuestionnaireSearch
      appearance="careui"
      facilityId={facilityId}
      subjectType="location"
      disabled={disabled}
      onSelect={(questionnaire) =>
        navigate(
          `/facility/${facilityId}/locations/${locationId}/questionnaire/${questionnaire.id}`,
        )
      }
      trigger={
        trigger ?? (
          <Button
            type="button"
            disabled={disabled}
            className="h-12 border border-emerald-950 bg-emerald-800 text-white shadow-md hover:bg-emerald-900 focus-visible:ring-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 md:h-10 [&_svg]:size-5"
          >
            <FilePlus2 className="size-4" />
            {t("submit_forms")}
          </Button>
        )
      }
    />
  );
}
