          label: t("settings"),
          href: `${baseUrl}/settings/general`,
          hideOnMobile: true,
        },
        { label: t("devices"), href: `${baseUrl}/settings/devices` },
        { label: device?.registered_name ?? t("device") },
      ]}
    />
  );
}

