    queryKey: [subjectType, facilityId, subjectId],
    queryFn: ({ signal }) =>
      subjectType === "location"
        ? query(locationApi.get, {
            pathParams: { facility_id: facilityId, id: subjectId },
          })({ signal })
        : query(deviceApi.retrieve, {
            pathParams: { facility_id: facilityId, id: subjectId },
          })({ signal }),
  });
  const resolvedSubjectName =
    subjectName ??
    (subjectQuery.data &&
      ("name" in subjectQuery.data
        ? subjectQuery.data.name
        : subjectQuery.data.registered_name));
  const SubjectIcon = subjectType === "device" ? Monitor : MapPin;
  const responsesQuery = useQuery({
    queryKey: [
