                          className="w-full lg:w-72"
                        />
                        <div className="w-full sm:w-auto flex justify-center sm:justify-start">
                          <Button
                            variant="primary"
                            onClick={handleAddLocation}
                            className="w-full sm:w-auto"
                          >
                            <CareIcon icon="l-plus" className="h-4 w-4 mr-2" />
                            {t("add_location")}
