export function useSubmitFillSession({
  forms,
  getStore,
  subject,
  continueDraftId,
  blockedFormLabels,
  onSuccess,
}: UseSubmitFillSessionArgs) {
  const { t } = useTranslation();
  const [serverErrors, setServerErrors] = useState<ServerValidationError[]>([]);

  const { mutate: submitBatch, isPending } = useMutation({
    // Silent: batch failures are handled here (panel + per-question), not
    // by the global error toast.
    // TODO: migrate to useBatchRequest once it can take pre-built batch
    // entries (these requests carry raw urls) and can opt out of the
    // global error toast.
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    mutationFn: mutate(batchApi.batchRequest, { silent: true }),
    // What the questionnaires' actions reported (`_actions` on each submit
    // result) is toasted by the mutation cache, like every other write.
    onSuccess: () => {
      setServerErrors([]);
      toast.success(t("questionnaire_submitted_successfully"));
      onSuccess();
    },
    onError: (error) => {
      if (hasBatchResults(error.cause)) {
        // An action that failed to evaluate (a reference to an unanswered
        // question the guard below could not see, a bad expression) is an
        // unhandled server error on the questionnaire's own request — the
        // batch rolls back and reports nothing per question. Name the
        // cause: it is the form's automation, not the clinician's input.
        const questionnaireIds = new Set(
          forms.map((form) => form.questionnaire.id),
        );
        if (
          error.cause.results.some(
            (result) =>
              result.status_code >= 500 &&
              questionnaireIds.has(result.reference_id),
          )
        ) {
          toast.error(t("questionnaire_actions_failed"));
          return;
        }
        const mapped = mapBatchErrors(
          error.cause.results,
          t("validation_failed"),
        );
"}

