import { FilePlus2 } from "lucide-react";
import { navigate } from "raviger";
import { ReactNode } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { QuestionnaireSearch } from "@/components/Questionnaire/QuestionnaireSearch";

interface ResourceFormPickerProps {
  facilityId: string;
  subjectType: "location" | "device";
  subjectId: string;
  trigger?: ReactNode;
  disabled?: boolean;
}

export function ResourceFormPicker({
  facilityId,
  subjectType,
  subjectId,
  trigger,
  disabled = false,
}: ResourceFormPickerProps) {
  const { t } = useTranslation();
  const baseUrl =
    subjectType === "location"
      ? `/facility/${facilityId}/locations/${subjectId}`
      : `/facility/${facilityId}/settings/devices/${subjectId}`;

  return (
    <QuestionnaireSearch
      appearance="careui"
      facilityId={facilityId}
      subjectType={subjectType}
      disabled={disabled}
      onSelect={(questionnaire) =>
        navigate(`${baseUrl}/questionnaire/${questionnaire.id}`)
      }
      trigger={
        trigger ?? (
          <Button
            type="button"
            disabled={disabled}
            className="h-12 border border-emerald-950 bg-emerald-800 text-white shadow-md hover:bg-emerald-900 focus-visible:ring-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 md:h-10 [&_svg]:size-5"
          >
            <FilePlus2 className="size-4" />
            {t("submit_forms")}
          </Button>
        )
      }
    />
  );
}
import { useQuery } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";

import { InnerPageHeader } from "@/components/Common/InnerPageHeader";

import query from "@/Utils/request/query";
import deviceApi from "@/types/device/deviceApi";

interface DevicePageHeaderProps {
  facilityId: string;
  facilityName: string;
  deviceId: string;
}

export function DevicePageHeader({
  facilityId,
  facilityName,
  deviceId,
}: DevicePageHeaderProps) {
  const { t } = useTranslation();
  const { data: device } = useQuery({
    queryKey: ["device", facilityId, deviceId],
    queryFn: query(deviceApi.retrieve, {
      pathParams: { facility_id: facilityId, id: deviceId },
    }),
  });
  const baseUrl = `/facility/${facilityId}`;

  return (
    <InnerPageHeader
      dataCy="facility-settings-page-header"
      breadcrumbs={[
        {
          label: facilityName,
          href: `${baseUrl}/overview`,
          hideOnMobile: true,
        },
        {
          label: t("settings"),
          href: `${baseUrl}/settings/general`,
          hideOnMobile: true,
        },
        { label: t("devices"), href: `${baseUrl}/settings/devices` },
        { label: device?.registered_name ?? t("device") },
      ]}
    />
  );
}

