import { FilePlus2 } from "lucide-react";
import { navigate } from "raviger";
import { ReactNode } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { QuestionnaireSearch } from "@/components/Questionnaire/QuestionnaireSearch";

interface ResourceFormPickerProps {
  facilityId: string;
  subjectType: "location" | "device";
  subjectId: string;
  trigger?: ReactNode;
  disabled?: boolean;
}

export function ResourceFormPicker({
  facilityId,
  subjectType,
  subjectId,
  trigger,
  disabled = false,
}: ResourceFormPickerProps) {
  const { t } = useTranslation();
  const baseUrl =
    subjectType === "location"
      ? `/facility/${facilityId}/locations/${subjectId}`
      : `/facility/${facilityId}/settings/devices/${subjectId}`;

  return (
    <QuestionnaireSearch
      appearance="careui"
      facilityId={facilityId}
      subjectType={subjectType}
      disabled={disabled}
      onSelect={(questionnaire) =>
        navigate(`${baseUrl}/questionnaire/${questionnaire.id}`)
      }
      trigger={
        trigger ?? (
          <Button
            type="button"
            disabled={disabled}
            className="h-12 border border-emerald-950 bg-emerald-800 text-white shadow-md hover:bg-emerald-900 focus-visible:ring-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 md:h-10 [&_svg]:size-5"
          >
            <FilePlus2 className="size-4" />
            {t("submit_forms")}
          </Button>
        )
      }
    />
  );
}
export type ResourceResponseSubjectType = "location" | "device";
import { usePath } from "raviger";
import { useTranslation } from "react-i18next";

import { getFacilitySettingsPageTitle } from "@/components/ui/sidebar/facility/settings/facility-settings-nav";

import { InnerPageHeader } from "@/components/Common/InnerPageHeader";

import { DevicePageHeader } from "@/pages/Facility/settings/devices/DevicePageHeader";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";

export function FacilitySettingsPageHeader() {
  const { t } = useTranslation();
  const { facilityId, facility } = useCurrentFacility();
  const path = usePath() ?? "";
  const baseUrl = `/facility/${facilityId}`;
  const deviceId = path.match(
    /^\/facility\/[^/]+\/settings\/devices\/([^/]+)(?:\/responses)?\/?$/,
  )?.[1];

  if (deviceId && deviceId !== "create") {
    return (
      <DevicePageHeader
        facilityId={facilityId}
        facilityName={facility?.name ?? t("facility")}
        deviceId={deviceId}
      />
    );
  }

  return (
    <InnerPageHeader
      dataCy="facility-settings-page-header"
      breadcrumbs={[
        {
          label: facility?.name ?? t("facility"),
          href: `${baseUrl}/overview`,
          hideOnMobile: true,
        },
        { label: t("settings"), href: `${baseUrl}/settings/general` },
        { label: getFacilitySettingsPageTitle(path, t) },
      ]}
    />
  );
}

