function NavLink({
  href,
  ariaLabel,
  isSelected,
  isActive,
  activeClass,
  exactActiveClass,
  className,
  onClick,
  children,
}: {
  href: string;
  ariaLabel?: string;
  isSelected: boolean;
  isActive?: boolean;
  activeClass?: string;
  exactActiveClass?: string;
  className?: string;
  onClick?: (e: React.MouseEvent) => void;
  children: ReactNode;
}) {
  const resolvedExact = exactActiveClass ?? activeClass;
  const { toggleSidebar, isMobile } = useSidebar();

  return (
    <ActiveLink
      href={href}
      aria-label={ariaLabel}
      basePath={isActive !== undefined ? "/" : undefined}
      aria-current={isActive ? "page" : undefined}
      data-active={isActive}
      className={className}
      activeClass={activeClass}
      exactActiveClass={resolvedExact}
      onClick={(e) => {
        if (isSelected) {
          e.preventDefault();
          if (isMobile) {
            toggleSidebar();
          }
        }
        onClick?.(e);
      }}
    >
      {children}
    </ActiveLink>
  );
}

