function NavItem({
  item,
  setOpen,
  appearance,
}: {
  item: NavigationLink;
  setOpen: (open: boolean) => void;
  appearance: NavAppearance;
}) {
  const path = usePath();
  const selected = path === item.url;
  const isCareUI = appearance === "careui";

  return (
    <NavLink
      href={item.url}
      isSelected={selected}
      isActive={isCareUI ? isNavigationActive(path, item.url) : undefined}
      className={cn(
        "w-full",
        isCareUI
          ? CAREUI_NAV_CLASSES
          : "rounded-md px-2 py-1.5 text-sm outline-none transition-colors hover:bg-gray-100 focus:bg-gray-100",
      )}
      activeClass={isCareUI ? undefined : "bg-gray-100 text-green-700"}
      onClick={() => setOpen(false)}
    >
      {item.name}
    </NavLink>
  );
}

function PopoverMenu({
  link,
  appearance,
}: {
  link: NavigationLink;
  appearance: NavAppearance;
}) {
  const [open, setOpen] = useState(false);
  const path = usePath();
  const isCareUI = appearance === "careui";
  const childActive = isCareUI
    ? !!link.children?.some(
        (child) =>
          child.visibility !== false && isNavigationActive(path, child.url),
      )
    : isChildActive(link);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <SidebarMenuButton
          aria-label={isCareUI ? link.name : undefined}
          tooltip={link.name}
          isActive={isCareUI && childActive}
          className={cn(
            isCareUI
              ? CAREUI_NAV_CLASSES
              : "cursor-pointer hover:bg-gray-200 hover:text-green-700",
            {
              "bg-white text-green-700 shadow": !isCareUI && childActive,
            },
          )}
        >
          {link.icon ? (
            link.icon
          ) : (
            <Avatar name={link.name} className="size-6 -m-1 rounded-sm" />
          )}
        </SidebarMenuButton>
      </PopoverTrigger>
      <PopoverContent
        side="right"
        align="start"
        className={cn(
          "w-48 p-1",
          isCareUI &&
            "w-60 rounded-xl border-neutral-200 bg-white text-neutral-950 shadow-md",
        )}
        aria-label={isCareUI ? link.name : undefined}
        onCloseAutoFocus={isCareUI ? undefined : (e) => e.preventDefault()}
      >
        <div className={cn("flex flex-col", isCareUI ? "gap-0.5" : "gap-1")}>
          {link.children
            ?.filter((item) => !isCareUI || item.visibility !== false)
            .map((subItem) => (
              <NavItem
                key={subItem.name}
                item={subItem}
                setOpen={setOpen}
                appearance={appearance}
              />
            ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}
import { usePath } from "raviger";
import { useTranslation } from "react-i18next";

import { InnerPageHeader } from "@/components/Common/InnerPageHeader";

import useCurrentLocation from "@/pages/Facility/locations/utils/useCurrentLocation";

export function LocationPageHeader() {
  const { t } = useTranslation();
  const { facilityId, locationId, location } = useCurrentLocation();
  const path = usePath() ?? "";
  const baseUrl = `/facility/${facilityId}/locations/${locationId}`;
  const section = path.slice(baseUrl.length);
  const pageTitles = [
    ["/responses", t("responses")],
    ["/forms", t("responses")],
    ["/beds", t("beds")],
    ["/service_requests", t("service_requests")],
    ["/medication_requests", t("prescription_queue")],
    ["/medication_dispense", t("dispense")],
    ["/medication_return", t("medication_return")],
    ["/inventory/internal/receive", t("to_receive")],
    ["/inventory/internal/dispatch", t("to_dispatch")],
    ["/inventory/external/orders", t("purchase_orders")],
    ["/inventory/external/deliveries", t("purchase_deliveries")],
    ["/inventory", t("inventory")],
    ["/schedule", t("schedule")],
    ["/appointments", t("appointments")],
    ["/queues", t("queues")],
  ];
  const pageTitle =
    pageTitles.find(([prefix]) => section.startsWith(prefix))?.[1] ??
    t("overview");

  return (
    <InnerPageHeader
      dataCy="location-page-header"
      breadcrumbs={[
        { label: location?.name ?? t("location"), href: `${baseUrl}/overview` },
        { label: pageTitle },
      ]}
    />
  );
}

