import { ChevronLeft, Settings, X } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { useSidebar } from "@/components/ui/sidebar";
import { TooltipComponent } from "@/components/ui/tooltip";

import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";

export function FacilitySettingsSidebarHeader() {
  const { t } = useTranslation();
  const { facilityId, facility, isFacilityLoading } = useCurrentFacility();
  const { state, isMobile, setOpenMobile } = useSidebar();
  const isCollapsed = state === "collapsed" && !isMobile;

  return (
    <div
      className={cn("flex min-w-0 flex-col gap-2 py-2", !isCollapsed && "px-2")}
    >
      <div className="flex min-h-8 items-center justify-between">
        <TooltipComponent content={t("back_to_facility")} side="right">
          <Button
            asChild
            variant="ghost"
            size={isCollapsed ? "icon" : "sm"}
            className={cn(
              "gap-1.5 text-neutral-600 hover:bg-neutral-200 hover:text-neutral-950 focus-visible:ring-2 focus-visible:ring-indigo-400",
              isCollapsed ? "size-8" : "-ml-1 h-8 px-2",
            )}
          >
            <Link
              href={`/facility/${facilityId}/overview`}
              basePath="/"
              aria-label={t("back_to_facility")}
              onClick={() => {
                if (isMobile) setOpenMobile(false);
              }}
            >
              <ChevronLeft className="size-4" />
              {!isCollapsed && <span>{t("back_to_facility")}</span>}
            </Link>
          </Button>
        </TooltipComponent>
        {isMobile && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-8 shrink-0 text-neutral-600 hover:bg-neutral-200 hover:text-neutral-950 focus-visible:ring-2 focus-visible:ring-indigo-400"
            onClick={() => setOpenMobile(false)}
            aria-label={t("close_sidebar")}
          >
            <X className="size-4" />
          </Button>
        )}
      </div>

      <div
        className={cn(
          "flex min-w-0 items-center rounded-[10px] border border-neutral-300 bg-white text-neutral-950",
          isCollapsed ? "size-8 justify-center" : "px-3 py-2.5",
        )}
        title={isCollapsed ? t("settings") : facility?.name}
      >
        {isCollapsed ? (
          <>
            <Settings className="size-4 text-neutral-600" aria-hidden="true" />
            <span className="sr-only">{t("settings")}</span>
          </>
        ) : (
          <div className="flex min-w-0 flex-col">
            <span className="text-[10px] font-semibold tracking-wider text-neutral-600 uppercase">
              {t("settings")}
            </span>
            <span className="truncate text-sm font-semibold">
              {facility?.name ??
                (isFacilityLoading ? t("loading") : t("facility"))}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}
import { usePath } from "raviger";
import { useTranslation } from "react-i18next";

import { getFacilitySettingsPageTitle } from "@/components/ui/sidebar/facility/settings/facility-settings-nav";

import { InnerPageHeader } from "@/components/Common/InnerPageHeader";

import { DevicePageHeader } from "@/pages/Facility/settings/devices/DevicePageHeader";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";

export function FacilitySettingsPageHeader() {
  const { t } = useTranslation();
  const { facilityId, facility } = useCurrentFacility();
  const path = usePath() ?? "";
  const baseUrl = `/facility/${facilityId}`;
  const deviceId = path.match(
    /^\/facility\/[^/]+\/settings\/devices\/([^/]+)(?:\/responses)?\/?$/,
  )?.[1];

  if (deviceId && deviceId !== "create") {
    return (
      <DevicePageHeader
        facilityId={facilityId}
        facilityName={facility?.name ?? t("facility")}
        deviceId={deviceId}
      />
    );
  }

  return (
    <InnerPageHeader
      dataCy="facility-settings-page-header"
      breadcrumbs={[
        {
          label: facility?.name ?? t("facility"),
          href: `${baseUrl}/overview`,
          hideOnMobile: true,
        },
        { label: t("settings"), href: `${baseUrl}/settings/general` },
        { label: getFacilitySettingsPageTitle(path, t) },
      ]}
    />
  );
}
import { TFunction } from "i18next";
import {
  Activity,
  BookOpen,
  Building2,
  ClipboardList,
  FileText,
  HeartPulse,
  IdCard,
  ListChecks,
  LucideIcon,
  MapPin,
  Monitor,
  Network,
  Package,
  Receipt,
  Stethoscope,
  Tags,
  TestTubeDiagonal,
  Ticket,
  Wallet,
} from "lucide-react";
import { Fragment } from "react";
import { useTranslation } from "react-i18next";

import { Separator } from "@/components/ui/separator";
import { NavigationLink, NavMain } from "@/components/ui/sidebar/nav-main";

import { getPermissions } from "@/common/Permissions";

import { usePermissions } from "@/context/PermissionContext";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";

interface SettingsPermissions {
  canListTokenCategories: boolean;
  canReadPatientIdentifierConfig: boolean;
  canListTemplate: boolean;
}

interface SettingsPage {
  path: string;
  title: string;
  icon: LucideIcon;
  permission?: keyof SettingsPermissions;
}

interface SettingsGroup {
  label?: string;
  pages: SettingsPage[];
}

const SETTINGS_GROUPS: SettingsGroup[] = [
  {
    pages: [{ path: "settings/general", title: "general", icon: Building2 }],
  },
  {
    label: "facility",
    pages: [
      { path: "settings/departments", title: "departments", icon: Network },
      { path: "settings/locations", title: "locations", icon: MapPin },
      { path: "settings/devices", title: "devices", icon: Monitor },
      {
        path: "settings/token_category",
        title: "token_category",
        icon: Ticket,
        permission: "canListTokenCategories",
      },
      {
        path: "settings/patient_identifier_config",
        title: "patient_identifier_config",
        icon: IdCard,
        permission: "canReadPatientIdentifierConfig",
      },
      { path: "settings/tag_config", title: "tag_config", icon: Tags },
    ],
  },
  {
    label: "clinical",
    pages: [
      {
        path: "settings/healthcare_services",
        title: "healthcare_services",
        icon: Stethoscope,
      },
      {
        path: "settings/specimen_definitions",
        title: "specimen_definitions",
        icon: TestTubeDiagonal,
      },
      {
        path: "settings/observation_definitions",
        title: "observation_definitions",
        icon: HeartPulse,
      },
      {
        path: "settings/activity_definitions",
        title: "activity_definitions",
        icon: Activity,
      },
    ],
  },
  {
    label: "forms",
    pages: [
      {
        path: "settings/questionnaires",
        title: "questionnaire_other",
        icon: ClipboardList,
      },
      { path: "settings/valuesets", title: "valuesets", icon: ListChecks },
      {
        path: "template",
        title: "templates",
        icon: FileText,
        permission: "canListTemplate",
      },
      {
        path: "settings/responses",
        title: "responses",
        icon: ClipboardList,
      },
    ],
  },
  {
    label: "inventory",
    pages: [
      {
        path: "settings/product_knowledge",
        title: "product_knowledge",
        icon: BookOpen,
      },
      { path: "settings/product", title: "product", icon: Package },
    ],
  },
  {
    label: "billing",
    pages: [
      { path: "settings/billing", title: "billing", icon: Wallet },
      {
        path: "settings/charge_item_definitions",
        title: "charge_item_definitions",
        icon: Receipt,
      },
    ],
  },
];

const BILLING_PAGES = [
  { path: "discount_codes", title: "discount_codes", header: "discount" },
  { path: "discount_components", title: "discount_components" },
  { path: "discount_configuration", title: "discount_configuration" },
  { path: "tax_codes", title: "tax_codes", header: "tax" },
  { path: "tax_components", title: "tax_components" },
  {
    path: "informational_codes",
    title: "informational_codes",
    header: "informational",
  },
  { path: "settings", title: "settings", header: "configuration" },
];

const matchesPage = (path: string, page: string) =>
  path === page || path.startsWith(`${page}/`);

export function getFacilitySettingsPageTitle(
  pathname: string,
  t: TFunction,
): string {
  const path =
    pathname
      .split(/[?#]/)[0]
      .match(/^\/facility\/[^/]+\/(.*)/)?.[1]
      .replace(/\/+$/, "") ?? "";

  const billingPage = BILLING_PAGES.find((page) =>
    matchesPage(path, `settings/billing/${page.path}`),
  );
  if (billingPage) return t(billingPage.title);

  const page = SETTINGS_GROUPS.flatMap((group) => group.pages).find((page) =>
    matchesPage(path, page.path),
  );
  return t(page?.title ?? "settings");
}

export function FacilitySettingsNav() {
  const { t } = useTranslation();
  const { facilityId, facility } = useCurrentFacility();
  const { hasPermission } = usePermissions();
  const permissions = getPermissions(
    hasPermission,
    facility?.permissions ?? [],
  );
  const baseUrl = `/facility/${facilityId}`;

  return (
    <>
      {SETTINGS_GROUPS.map((group, index) => {
        const links: NavigationLink[] = group.pages.map((page) => ({
          name: t(page.title),
