              <p className="rounded-md bg-neutral-50 px-3 py-2 text-sm leading-6 break-words whitespace-pre-wrap text-neutral-600">
                <span className="font-medium">{t("note")}: </span>
                {answer.note}
              </p>
            )}
          </dd>
        </dl>,
