      <h1 className="text-3xl leading-9 font-bold tracking-tight">
        {t("general")}
      </h1>
      <FacilityHome
        facilityId={facilityId}
        appearance="settings"
        renderSettingsActions={(disabled) => (
          <FacilityOverviewActions
            facilityId={facilityId}
            disabled={disabled}
          />
        )}
      />
    </div>
  );
}
import {
